// Spanish grammar lessons, one per grammar point (P.skills): an intro, the course in parts, examples, traps, a tip.
// Shown in Cours › Grammaire. Written for Pablolinguo.
(function(){
const P = window.PACKS && window.PACKS.es; if(!P) return;
P.lessons = Object.assign(P.lessons || {}, {
"es_ser_estar":{"intro":"Pour te présenter, dire d'où tu viens ou comment tu te sens, l'espagnol a deux verbes « être ». Choisir le bon, c'est la base de toute conversation.","parts":[{"h":"Deux verbes, deux questions","p":"SER répond à « qui es-tu ? » : ton identité, ton métier, ton origine, ton caractère.\n\nESTAR répond à « comment vas-tu ? » et « où es-tu ? » : un état du moment ou un lieu.","rows":[["yo","soy / estoy","Soy Ana. Estoy bien."],["tú","eres / estás",""],["él, ella, usted","es / está",""],["nosotros","somos / estamos",""],["vosotros","sois / estáis","en Espagne seulement"],["ellos, ellas, ustedes","son / están",""]]},{"h":"Quand prendre ser","p":"Avec ser, tu dis ce qu'est la personne ou la chose, de façon durable : nationalité, métier, caractère, couleur.\n\nAttention : pas d'article devant un métier. On dit es médica, pas « es una médica »."},{"h":"Quand prendre estar","p":"Avec estar, tu décris un état qui peut changer : fatigué, content, malade, occupé.\n\nEt surtout, estar sert à situer : où est la gare, où est ton téléphone. Même pour une ville qui ne bougera jamais : Madrid está en España."},{"h":"Un adjectif, deux sens","p":"Certains adjectifs changent de sens selon le verbe. C'est la preuve que le choix compte vraiment.","rows":[["ser aburrido","Juan es aburrido.","il est ennuyeux"],["estar aburrido","Juan está aburrido.","il s'ennuie"],["ser listo","Eres muy lista.","tu es intelligente"],["estar listo","¿Estás lista?","tu es prête ?"]]}],"ex":[["Soy francés y vivo en Lyon.","Je suis français et j'habite à Lyon.","origine : ser"],["Mi hermana es profesora.","Ma sœur est professeure.","métier, sans article"],["Hoy estoy muy cansada.","Aujourd'hui, je suis très fatiguée.","état du moment"],["¿Dónde está el baño?","Où sont les toilettes ?","lieu : estar"],["La sopa está fría.","La soupe est froide.","son état en ce moment"],["Mis padres son muy simpáticos.","Mes parents sont très sympathiques.","caractère"],["Estamos en casa.","Nous sommes à la maison.",""],["Sevilla está en el sur de España.","Séville est dans le sud de l'Espagne.","lieu permanent : estar quand même"]],"traps":[["Soy cansado.","Estoy cansado.","La fatigue est un état passager, donc estar."],["Madrid es en España.","Madrid está en España.","Un lieu prend toujours estar, même s'il ne change pas."],["Es una médica.","Es médica.","Pas d'article devant un métier après ser."]],"tip":"Qui tu es, c'est ser ; comment et où tu es, c'est estar."},
"es_articulos":{"intro":"Pour demander de l'eau à table ou dire que ta main te fait mal, il te faut le bon article. Bonne nouvelle : l'espagnol n'en a que quatre au singulier.","parts":[{"h":"Les articles","p":"Comme en français, un nom est masculin ou féminin, et l'article le montre tout de suite.","rows":[["el","el libro","le (masculin)"],["la","la casa","la (féminin)"],["un","un perro","un"],["una","una mesa","une"],["los / las","los libros, las casas","les"],["unos / unas","unos amigos","des"]]},{"h":"Des genres qui ne suivent pas le français","p":"La plupart des mots en -o sont masculins et ceux en -a féminins. Mais le genre change parfois d'une langue à l'autre.\n\nPour ces mots, apprends toujours le nom avec son article, comme un seul bloc.","rows":[["la leche","le lait","féminin en espagnol"],["la sangre","le sang","féminin en espagnol"],["el valle","la vallée","masculin en espagnol"],["el color","la couleur","masculin en espagnol"],["el árbol","l'arbre","« l' » ne dit rien, el si"],["la mano","la main","féminin malgré le -o"]]},{"h":"Les mots en -ma","p":"Beaucoup de mots en -ma viennent du grec et sont masculins : el problema, el tema, el idioma, el sistema. El día est masculin aussi, malgré son -a.\n\nMais pas tous les mots en -ma : la cama (le lit) reste féminin."},{"h":"El agua, mais las aguas","p":"Devant un nom féminin qui commence par a ou ha accentué, on met el au singulier, pour éviter « la agua ». Le mot reste féminin : el agua fría, mucha hambre.\n\nAu pluriel, la règle disparaît : las aguas. Même chose pour el aula, las aulas."}],"ex":[["El problema es el precio.","Le problème, c'est le prix.","problema : masculin"],["Me duele la mano.","J'ai mal à la main.","mano : féminin"],["¿Me das un vaso de agua?","Tu me donnes un verre d'eau ?",""],["El agua está muy fría.","L'eau est très froide.","el, mais fría au féminin"],["Quiero un café con leche.","Je veux un café au lait.","la leche"],["Hay un árbol en el jardín.","Il y a un arbre dans le jardin.",""],["Es un buen día para pasear.","C'est une bonne journée pour se promener.","el día : masculin"],["Tengo una idea.","J'ai une idée.",""]],"traps":[["La problema es grave.","El problema es grave.","Les mots grecs en -ma sont masculins."],["La agua está fría.","El agua está fría.","Devant un a accentué, on dit el au singulier."],["El agua está frío.","El agua está fría.","Agua reste féminin : l'adjectif s'accorde au féminin."]],"tip":"Apprends chaque nom avec son article : el problema, la mano, el agua."},
"es_plurales":{"intro":"Deux cafés, trois amis, plusieurs villes : dès que tu commandes ou décris, il te faut le pluriel. En espagnol, il s'entend toujours, car le s final se prononce.","parts":[{"h":"Voyelle : on ajoute -s","p":"Si le mot finit par une voyelle, ajoute simplement -s. L'article passe aussi au pluriel : el devient los, la devient las.","rows":[["casa","casas",""],["libro","libros",""],["café","cafés","voyelle accentuée aussi"],["la chica","las chicas",""]]},{"h":"Consonne : on ajoute -es","p":"Si le mot finit par une consonne, ajoute -es.\n\nL'accent écrit peut disparaître ou apparaître : c'est pour garder la même syllabe forte.","rows":[["ciudad","ciudades",""],["árbol","árboles",""],["canción","canciones","l'accent disparaît"],["joven","jóvenes","l'accent apparaît"]]},{"h":"Le z devient c","p":"Un mot en -z fait son pluriel en -ces : l'espagnol n'écrit presque jamais z devant e.","rows":[["lápiz","lápices","crayon"],["vez","veces","fois"],["luz","luces","lumière"],["pez","peces","poisson"]]},{"h":"Les adjectifs suivent","p":"L'adjectif s'accorde en genre et en nombre, comme en français, avec la même règle : voyelle -s, consonne -es.\n\nSi le groupe mélange masculin et féminin, on prend le masculin : los chicos y las chicas son simpáticos."}],"ex":[["Las ciudades españolas son bonitas.","Les villes espagnoles sont jolies.",""],["Tengo dos lápices rojos.","J'ai deux crayons rouges.","lápiz devient lápices"],["Los árboles del parque son muy altos.","Les arbres du parc sont très hauts.",""],["Dos cafés, por favor.","Deux cafés, s'il vous plaît.",""],["Las hojas son verdes.","Les feuilles sont vertes.","verde devient verdes"],["Mis amigos son muy jóvenes.","Mes amis sont très jeunes.","joven prend un accent au pluriel"],["Voy al cine tres veces al mes.","Je vais au cinéma trois fois par mois.",""],["Las luces están encendidas.","Les lumières sont allumées.",""]],"traps":[["Los lápizes","Los lápices","Le z devient c devant -es."],["Las ciudads","Las ciudades","Après une consonne, on ajoute -es, pas seulement -s."],["Las casas son blanca.","Las casas son blancas.","L'adjectif prend aussi la marque du pluriel."]],"tip":"Voyelle, un -s ; consonne, un -es ; et le z se change en c."},
"es_hay":{"intro":"En ville, tu veux savoir s'il y a une pharmacie, puis où elle se trouve. En espagnol, ce sont deux questions différentes : hay et está.","parts":[{"h":"Hay : il y a","p":"Hay vient du verbe haber. Il ne change jamais, au singulier comme au pluriel.\n\nTu l'utilises pour dire qu'une chose existe quelque part. Après hay, on trouve un, una, un chiffre, mucho, ou un nom sans article.","rows":[["hay + un / una","Hay un banco aquí.",""],["hay + chiffre","Hay dos bancos.","hay ne change pas"],["hay + mucho","Hay mucha gente.",""],["hay + nom seul","¿Hay pan?","du pain : pas d'article"]]},{"h":"Está : se trouver","p":"Quand tu parles d'une chose précise, déjà connue, tu la situes avec estar. Tu la reconnais à el, la, mi, tu, ou à un nom propre.\n\nAu pluriel, estar s'accorde : están.","rows":[["el / la + está","El banco está allí.",""],["mi / tu + está","Mi coche está en la calle.",""],["los / las + están","Las llaves están en la mesa.","pluriel : están"],["¿Dónde está…?","¿Dónde está la estación?","la question du voyageur"]]},{"h":"Comment choisir","p":"Demande-toi : est-ce que je découvre la chose, ou est-ce que je la situe ? Découvrir, c'est hay. Situer une chose connue, c'est estar.\n\nEn français, on entend parfois « il y a la gare là-bas ». En espagnol, jamais « hay la estación »."}],"ex":[["Hay una farmacia cerca de aquí.","Il y a une pharmacie près d'ici.",""],["La farmacia está en la plaza.","La pharmacie est sur la place.","chose précise : estar"],["¿Hay pan?","Est-ce qu'il y a du pain ?","pas d'article"],["Hoy hay mucha gente en la playa.","Aujourd'hui, il y a beaucoup de monde à la plage.",""],["¿Dónde están mis gafas?","Où sont mes lunettes ?","pluriel : están"],["En mi calle hay tres restaurantes.","Dans ma rue, il y a trois restaurants.","hay ne change pas"],["No hay problema.","Il n'y a pas de problème.",""],["Madrid está en el centro de España.","Madrid est au centre de l'Espagne.",""]],"traps":[["Hay la estación cerca.","La estación está cerca.","Une chose précise (el, la, mi) se situe avec estar."],["¿Dónde hay la estación?","¿Dónde está la estación?","Pour chercher une chose précise, on dit dónde está."],["Están dos bancos en la calle.","Hay dos bancos en la calle.","Pour dire qu'une chose existe, c'est hay."]],"tip":"Hay pour découvrir, está pour situer."},
"es_gustar":{"intro":"Parler de ce que tu aimes, c'est le début de toute rencontre. Mais en espagnol, on ne dit pas « j'aime le café » : on dit « le café me plaît ».","parts":[{"h":"La chose aimée est le sujet","p":"Gustar veut dire plaire. Dans me gusta el café, le sujet est el café : c'est lui qui plaît. Toi, tu es juste me.\n\nLe verbe s'accorde donc avec la chose, pas avec la personne.","rows":[["me gusta + singulier","Me gusta el café.",""],["me gusta + infinitif","Me gusta bailar.","même plusieurs : me gusta leer y cantar"],["me gustan + pluriel","Me gustan los perros.",""]]},{"h":"Pour chaque personne","p":"Seul le petit pronom change selon la personne. Gusta ou gustan dépend toujours de la chose aimée.","rows":[["me","me gusta","à moi"],["te","te gusta","à toi"],["le","le gusta","à lui, à elle, à vous (usted)"],["nos","nos gusta","à nous"],["os","os gusta","à vous, en Espagne"],["les","les gusta","à eux, à elles"]]},{"h":"Préciser ou insister avec a","p":"Pour nommer la personne, ajoute a devant : a mi hermano le gusta. Le pronom le reste obligatoire.\n\nPour insister, on dit a mí, a ti : a mí me gusta el té, ¿y a ti? La négation se place devant le pronom : no me gusta."}],"ex":[["Me gusta mucho el chocolate.","J'aime beaucoup le chocolat.",""],["Me gustan los gatos.","J'aime les chats.","pluriel : gustan"],["¿Te gusta bailar?","Tu aimes danser ?",""],["A mi hermano no le gusta correr.","Mon frère n'aime pas courir.","le reste obligatoire"],["Nos gusta comer en la terraza.","Nous aimons manger en terrasse.",""],["A mis padres les gustan las películas antiguas.","Mes parents aiment les vieux films.",""],["A mí me gusta el té, ¿y a ti?","Moi, j'aime le thé, et toi ?","a mí pour insister"]],"traps":[["Yo gusto el café.","Me gusta el café.","Gustar veut dire plaire : la chose aimée est le sujet."],["Me gusta los perros.","Me gustan los perros.","Le verbe s'accorde avec la chose aimée, ici au pluriel."],["A mi hermano gusta correr.","A mi hermano le gusta correr.","Le pronom le est obligatoire, même avec a mi hermano."]],"tip":"Ce n'est pas toi qui aimes, c'est la chose qui te plaît : me gusta, me gustan."},
"es_presente":{"intro":"Dire où tu habites, ce que tu manges, quelle langue tu parles : tout ça se fait au présent. Trois modèles suffisent pour presque tous les verbes réguliers.","parts":[{"h":"Trois familles","p":"Un verbe espagnol finit par -ar, -er ou -ir. Pour le conjuguer, on enlève cette fin et on ajoute la terminaison de la personne.\n\nLes verbes en -er et en -ir se ressemblent beaucoup : seuls nosotros et vosotros changent.","rows":[["yo","hablo, como, vivo",""],["tú","hablas, comes, vives",""],["él, ella, usted","habla, come, vive",""],["nosotros","hablamos, comemos, vivimos","-ir : -imos"],["vosotros","habláis, coméis, vivís","-ir : -ís"],["ellos, ustedes","hablan, comen, viven",""]]},{"h":"Pas besoin de pronom","p":"La terminaison dit déjà qui parle : hablo, c'est forcément moi. On omet donc yo, tú, él la plupart du temps.\n\nOn les garde pour insister ou pour opposer deux personnes : yo trabajo, ¿y tú?"},{"h":"Un présent, plusieurs usages","p":"Comme en français, le présent sert pour maintenant, pour les habitudes et même pour un futur proche : mañana trabajo.\n\nPour poser une question, l'ordre des mots ne change pas. L'intonation monte, et on écrit ¿ au début."}],"ex":[["Vivo en Lyon con mi familia.","J'habite à Lyon avec ma famille.",""],["¿Hablas inglés?","Tu parles anglais ?",""],["Comemos a las dos.","Nous mangeons à deux heures.","horaire typique en Espagne"],["Mi madre trabaja en un banco.","Ma mère travaille dans une banque.",""],["¿Dónde viven tus abuelos?","Où habitent tes grands-parents ?",""],["Siempre bebo agua en las comidas.","Je bois toujours de l'eau aux repas.","habitude"],["Los sábados escribo a mis amigos.","Le samedi, j'écris à mes amis.",""],["Mañana trabajo hasta las ocho.","Demain, je travaille jusqu'à huit heures.","présent pour un futur proche"]],"traps":[["Vivemos en Lyon.","Vivimos en Lyon.","Les verbes en -ir font -imos, pas -emos."],["Ella trabajas en un banco.","Ella trabaja en un banco.","À la troisième personne, pas de -s final."],["Yo hablo español y yo vivo en París.","Hablo español y vivo en París.","Répéter yo sonne lourd : la terminaison suffit."]],"tip":"Enlève -ar, -er, -ir et laisse la terminaison dire qui parle."},
"es_tener_ir":{"intro":"Dire ton âge, dire que tu as faim, dire où tu vas : deux verbes, tener et ir, font une grande partie du travail. Ils sont irréguliers, donc on les apprend par cœur.","parts":[{"h":"Les deux verbes","p":"Retiens bien ces formes : tu vas t'en servir tous les jours.","rows":[["yo","tengo / voy",""],["tú","tienes / vas",""],["él, ella, usted","tiene / va",""],["nosotros","tenemos / vamos",""],["vosotros","tenéis / vais","en Espagne"],["ellos, ustedes","tienen / van",""]]},{"h":"Tener : avoir","p":"Tener veut dire avoir. Comme en français, il sert pour l'âge et les sensations : la faim, la soif, le froid, le chaud, la peur.\n\nAttention : pour la météo, on dit hace frío. Tener frío, c'est toi qui as froid.","rows":[["tener … años","Tengo 30 años.","l'âge"],["tener hambre","Tengo mucha hambre.","hambre est féminin : mucha"],["tener sed","¿Tienes sed?",""],["tener frío","Tengo frío.","toi, tu as froid"]]},{"h":"Ir a : aller quelque part","p":"Ir veut dire aller, et la destination se dit avec a. Devant el, a + el devient al : voy al cine. Avec la, rien ne change : voy a la playa.\n\nPour demander où quelqu'un va, on dit ¿adónde vas? ou ¿a dónde vas?"}],"ex":[["Tengo treinta años.","J'ai trente ans.",""],["¿Cuántos años tienes?","Quel âge as-tu ?","mot à mot : combien d'années as-tu"],["Tengo mucha hambre.","J'ai très faim.",""],["Mi hermano tiene dos hijos.","Mon frère a deux enfants.",""],["Vamos al mercado.","Nous allons au marché.","a + el = al"],["Esta tarde voy a la playa.","Cet après-midi, je vais à la plage.",""],["¿Adónde vas?","Où vas-tu ?",""],["Mis padres van a Madrid en tren.","Mes parents vont à Madrid en train.",""]],"traps":[["Estoy hambre.","Tengo hambre.","La faim se dit avec tener, comme avec avoir en français."],["Voy a el cine.","Voy al cine.","A + el se contracte toujours en al."],["Soy treinta años.","Tengo treinta años.","L'âge se dit avec tener, jamais avec ser."]],"tip":"Tengo pour l'âge et la faim, voy al pour la destination."},
"es_indefinido":{"intro":"Raconter ton week-end, un voyage ou ce que tu as mangé hier : c'est le rôle de l'indefinido. C'est le temps du récit, celui des actions finies.","parts":[{"h":"Les terminaisons","p":"On enlève -ar, -er, -ir. Les verbes en -er et en -ir ont les mêmes terminaisons.\n\nRegarde les accents de yo et él : hablé, habló. Ils changent le sens, car hablo est le présent.","rows":[["yo","hablé / comí",""],["tú","hablaste / comiste",""],["él, ella, usted","habló / comió",""],["nosotros","hablamos / comimos","hablamos : même forme qu'au présent"],["vosotros","hablasteis / comisteis",""],["ellos, ustedes","hablaron / comieron",""]]},{"h":"Quand l'utiliser","p":"L'indefinido raconte une action terminée, placée à un moment précis du passé. Les mots qui l'appellent : ayer, anoche, el sábado, la semana pasada, en 2020.\n\nEn français, tu le traduis le plus souvent par un passé composé : ayer comí paella, hier j'ai mangé une paella."},{"h":"Les irréguliers à connaître","p":"Les verbes les plus courants sont irréguliers, et leurs formes n'ont pas d'accent écrit.\n\nFui sert à la fois pour ir et pour ser : le contexte fait la différence.","rows":[["ir / ser","fui, fuiste, fue, fuimos, fueron","fui a Madrid, fue genial"],["hacer","hice, hiciste, hizo","hizo avec un z"],["tener","tuve, tuviste, tuvo",""],["estar","estuve, estuviste, estuvo",""],["ver","vi, viste, vio","pas d'accent"]]}],"ex":[["Ayer comí paella con mis primos.","Hier, j'ai mangé une paella avec mes cousins.",""],["El verano pasado fuimos a Madrid.","L'été dernier, nous sommes allés à Madrid.","fuimos : ir"],["¿Qué hiciste el sábado?","Qu'est-ce que tu as fait samedi ?",""],["Ella no llamó.","Elle n'a pas appelé.",""],["Anoche vi una película muy buena.","Hier soir, j'ai vu un très bon film.",""],["El concierto fue increíble.","Le concert a été incroyable.","fue : ser"],["Estuve dos horas en la cola.","Je suis resté deux heures dans la file.",""],["Mis padres se casaron en 1995.","Mes parents se sont mariés en 1995.",""]],"traps":[["Ayer hablo con Ana.","Ayer hablé con Ana.","Sans accent, hablo est le présent : l'accent change le temps."],["Fuí al cine.","Fui al cine.","Fui, fue et vio ne prennent pas d'accent."],["Ayer he comido paella.","Ayer comí paella.","Avec ayer, on emploie l'indefinido, pas haber."]],"tip":"Un moment précis et une action finie : ayer comí, el sábado fui."},
"es_imperfecto":{"intro":"Raconter ton enfance, décrire ton ancienne maison ou le temps qu'il faisait : c'est le travail de l'imperfecto. Il ressemble beaucoup à l'imparfait français.","parts":[{"h":"Deux terminaisons seulement","p":"Les verbes en -ar prennent -aba. Les verbes en -er et -ir prennent -ía, avec un accent sur le i.\n\nYo et él ont la même forme : le contexte ou le pronom lève le doute.","rows":[["yo","jugaba / vivía",""],["tú","jugabas / vivías",""],["él, ella, usted","jugaba / vivía","comme yo"],["nosotros","jugábamos / vivíamos","accent sur -ába-"],["vosotros","jugabais / vivíais",""],["ellos, ustedes","jugaban / vivían",""]]},{"h":"Habitudes et descriptions","p":"L'imperfecto dit ce qui se passait souvent : de niño, jugaba al fútbol. Les mots qui l'appellent : antes, de pequeño, siempre, todos los días.\n\nIl sert aussi à décrire un décor : le temps, l'heure, l'âge, l'apparence. Hacía frío, tenía diez años, era de noche."},{"h":"Trois irréguliers, pas plus","p":"C'est un des temps les plus faciles de l'espagnol : seuls trois verbes sont irréguliers.","rows":[["ser","era, eras, era, éramos, eran",""],["ir","iba, ibas, iba, íbamos, iban",""],["ver","veía, veías, veía, veíamos, veían","garde le e de ver"]]}],"ex":[["De niño, jugaba al fútbol todos los días.","Enfant, je jouais au foot tous les jours.","habitude"],["Antes vivíamos en el campo.","Avant, nous habitions à la campagne.",""],["Hacía frío y llovía.","Il faisait froid et il pleuvait.","description du temps"],["Mi abuela era muy alta.","Ma grand-mère était très grande.","ser : era"],["Los domingos íbamos a la playa.","Le dimanche, nous allions à la plage.","ir : íbamos"],["Cuando tenía quince años, quería ser piloto.","Quand j'avais quinze ans, je voulais être pilote.",""],["Eran las diez de la noche.","Il était dix heures du soir.","l'heure se dit avec ser"],["Siempre veíamos dibujos animados por la mañana.","Nous regardions toujours des dessins animés le matin.",""]],"traps":[["Cuando era pequeño, jugué al fútbol.","Cuando era pequeño, jugaba al fútbol.","Une habitude du passé se dit à l'imperfecto."],["Antes jugabamos mucho.","Antes jugábamos mucho.","À nosotros, la terminaison prend un accent : -ábamos."],["Yo iva al colegio en bici.","Yo iba al colegio en bici.","Iba s'écrit avec un b, comme les terminaisons en -aba."]],"tip":"L'imperfecto plante le décor et dit les habitudes : -aba, -ía, et seulement era, iba, veía à part."},
"es_reflexivos":{"intro":"Raconter ta journée, du réveil au coucher, demande beaucoup de verbes pronominaux. Ils marchent presque comme en français, avec quelques surprises.","parts":[{"h":"Le pronom devant le verbe","p":"Comme en français, le pronom se place devant le verbe conjugué et change avec la personne.\n\nÀ l'infinitif, le pronom se colle à la fin : levantarse, ducharse.","rows":[["yo","me levanto",""],["tú","te levantas",""],["él, ella, usted","se levanta",""],["nosotros","nos levantamos",""],["vosotros","os levantáis","en Espagne"],["ellos, ustedes","se levantan",""]]},{"h":"Avec un infinitif","p":"Après un verbe comme tener que ou querer, le pronom se colle à l'infinitif, ou se met devant le verbe conjugué : tengo que levantarme, me tengo que levantar.\n\nDans les deux cas, il garde la personne : me pour yo, te pour tú."},{"h":"Ce qui ne colle pas au français","p":"Certains verbes sont pronominaux dans une langue et pas dans l'autre. Ils sont peu nombreux, mais très fréquents.\n\nAutre différence : avec une partie du corps, on met l'article, pas le possessif. Me lavo las manos, je me lave les mains.","rows":[["quedarse","Me quedo en casa.","rester : pronominal en espagnol"],["irse","Me voy.","je m'en vais, je pars"],["despertarse","Me despierto a las seis.","se réveiller : comme en français"],["llamarse","Me llamo Ana.","s'appeler"],["acordarse de","No me acuerdo.","se souvenir"],["casarse","Se casan en mayo.","se marier"]]}],"ex":[["Me levanto a las siete.","Je me lève à sept heures.",""],["¿Cómo te llamas?","Comment tu t'appelles ?",""],["Nos acostamos tarde los viernes.","Nous nous couchons tard le vendredi.",""],["Ella se ducha por la mañana.","Elle se douche le matin.",""],["Hoy me quedo en casa.","Aujourd'hui, je reste à la maison.","rester : quedarse"],["Me lavo los dientes después de comer.","Je me brosse les dents après le repas.","article, pas possessif"],["Mañana tengo que despertarme temprano.","Demain, je dois me réveiller tôt.","pronom collé à l'infinitif"],["Ya es tarde, me voy.","Il est déjà tard, je m'en vais.",""]],"traps":[["Quedo en casa.","Me quedo en casa.","Rester se dit quedarse, avec le pronom."],["Me lavo mis manos.","Me lavo las manos.","Avec une partie du corps, on met l'article, pas le possessif."],["Tengo que levantarse temprano.","Tengo que levantarme temprano.","Le pronom collé à l'infinitif change aussi avec la personne."]],"tip":"Me levanto, te levantas, se levanta : le pronom suit toujours la personne."},
"es_ir_a":{"intro":"Parler de tes projets du week-end ou annoncer qu'il va pleuvoir : l'espagnol utilise le futur proche, très courant à l'oral. Il ressemble au français, avec un petit mot en plus.","parts":[{"h":"La formule","p":"On conjugue ir au présent, on ajoute a, puis l'infinitif. Le a est obligatoire, toujours.\n\nC'est l'erreur numéro un des francophones, car « je vais manger » n'a pas de préposition.","rows":[["voy a","Voy a comer.",""],["vas a","¿Vas a venir?",""],["va a","Va a llover.",""],["vamos a","Vamos a salir.",""],["vais a","¿Vais a cenar aquí?","en Espagne"],["van a","Van a llegar tarde.",""]]},{"h":"Quand l'utiliser","p":"Ir a sert pour un projet, une intention ou une chose qu'on voit venir : mira las nubes, va a llover.\n\nÀ l'oral, il est souvent plus naturel que le futur simple. La négation se place devant ir : no voy a salir."},{"h":"Où mettre les pronoms","p":"Un pronom se colle à la fin de l'infinitif, ou se place devant ir : voy a llamarte, te voy a llamar. Les deux sont corrects.\n\nSelon le ton, vamos a + infinitif peut aussi être une invitation : ¡vamos a comer!, allez, on mange !"}],"ex":[["Voy a llamar a mi madre.","Je vais appeler ma mère.","deux a : celui de ir a, et celui devant la personne"],["Va a llover.","Il va pleuvoir.",""],["¿Qué vas a hacer este fin de semana?","Qu'est-ce que tu vas faire ce week-end ?",""],["Vamos a comprar un ordenador.","Nous allons acheter un ordinateur.",""],["Mis amigos van a venir a cenar.","Mes amis vont venir dîner.",""],["No voy a salir esta noche.","Je ne vais pas sortir ce soir.","no devant ir"],["Te voy a contar un secreto.","Je vais te raconter un secret.","pronom devant ir"],["El tren va a salir en cinco minutos.","Le train va partir dans cinq minutes.",""]],"traps":[["Voy comer.","Voy a comer.","Le a entre ir et l'infinitif est obligatoire."],["Voy a no salir.","No voy a salir.","La négation se place devant ir."],["Voy a llamar mi madre.","Voy a llamar a mi madre.","Devant une personne complément, l'espagnol ajoute aussi a."]],"tip":"Je vais faire, c'est voy a hacer : jamais sans le a."},
"es_comparativos":{"intro":"Comparer deux trains, deux restaurants ou ta taille avec celle de ta sœur : tu le fais tous les jours. En espagnol, la formule est courte et régulière.","parts":[{"h":"Plus, moins, aussi","p":"Pour plus, on dit más ; pour moins, menos. Le « que » français reste que.\n\nAprès que, on met le pronom sujet : más alto que yo, más rápida que tú.","rows":[["más … que","Es más rápido que el bus.","plus … que"],["menos … que","Es menos caro que el hotel.","moins … que"],["tan … como","Es tan alta como tú.","aussi … que"],["tanto(s) … como","Tiene tantos amigos como tú.","autant de … que"]]},{"h":"L'égalité","p":"Devant un adjectif, on dit tan … como : tan alto como. Devant un nom, tanto s'accorde avec lui : tanto dinero, tanta paciencia, tantos amigos, tantas ideas.\n\nAttention : pour l'égalité, le second mot est como, pas que."},{"h":"Les irréguliers","p":"Comme en français, bon et mauvais ont leur propre forme.\n\nMayor et menor servent surtout pour l'âge : mi hermano mayor, c'est mon grand frère.","rows":[["bueno","mejor","meilleur, mieux"],["malo","peor","pire"],["viejo (personnes)","mayor","plus âgé"],["joven","menor","plus jeune"]]},{"h":"Le plus, le meilleur","p":"Pour « le plus », ajoute l'article : el más alto, la más cara, el mejor. Le complément se dit avec de : el mejor restaurante de la ciudad."}],"ex":[["El tren es más rápido que el autobús.","Le train est plus rapide que le bus.",""],["Mi hermana es más alta que yo.","Ma sœur est plus grande que moi.","que yo, pas que mí"],["Este hotel es menos caro que el otro.","Cet hôtel est moins cher que l'autre.",""],["Es el mejor restaurante de la ciudad.","C'est le meilleur restaurant de la ville.",""],["Tiene tantos amigos como tú.","Il a autant d'amis que toi.",""],["Hoy hace tanto calor como ayer.","Aujourd'hui, il fait aussi chaud qu'hier.","calor est un nom : tanto"],["Mi hermano mayor vive en Chile.","Mon grand frère habite au Chili.",""],["Esta película es peor que la primera.","Ce film est pire que le premier.",""]],"traps":[["Este café es más bueno que el otro.","Este café es mejor que el otro.","Pour la qualité, on dit mejor, comme « meilleur »."],["Es tan alto que tú.","Es tan alto como tú.","Pour l'égalité, on dit como, pas que."],["Es más alta que mí.","Es más alta que yo.","Après que, on met yo, tú, pas mí, ti."]],"tip":"Más ou menos avec que, tan ou tanto avec como."},
"es_gerundio":{"intro":"Au téléphone, on te demande ce que tu fais : je suis en train de cuisiner, de travailler. L'espagnol dit ça avec estar et un gérondif, et il le dit très souvent.","parts":[{"h":"Former le gérondif","p":"On enlève -ar, -er, -ir. Les verbes en -ar prennent -ando, ceux en -er et -ir prennent -iendo.\n\nLe gérondif ne change jamais, quelle que soit la personne.","rows":[["hablar","hablando",""],["comer","comiendo",""],["vivir","viviendo",""],["leer","leyendo","le i entre deux voyelles devient y"],["dormir","durmiendo","o devient u"],["pedir","pidiendo","e devient i"]]},{"h":"Estar + gérondif","p":"On conjugue estar et on ajoute le gérondif : estoy trabajando, están durmiendo. C'est l'équivalent de « être en train de ».\n\nL'espagnol l'emploie bien plus que le français. Là où tu dis « je travaille » au téléphone, un Espagnol dira souvent estoy trabajando."},{"h":"Avec les pronoms","p":"Un pronom se colle à la fin du gérondif, avec un accent pour garder la prononciation : estoy duchándome.\n\nOu bien il se place devant estar : me estoy duchando. Les deux sont corrects."}],"ex":[["Estoy trabajando, te llamo luego.","Je suis en train de travailler, je te rappelle plus tard.",""],["¿Qué estás haciendo?","Qu'est-ce que tu fais ?","très courant au téléphone"],["Los niños están durmiendo.","Les enfants dorment.","dormir : durmiendo"],["Ella está leyendo un libro.","Elle est en train de lire un livre.","leer : leyendo"],["Está lloviendo mucho.","Il pleut beaucoup.","ce qui se passe maintenant"],["Estamos comiendo en un restaurante mexicano.","Nous sommes en train de manger dans un restaurant mexicain.",""],["Me estoy duchando, espera un momento.","Je suis sous la douche, attends un moment.","pronom devant estar"],["¿Me estás escuchando?","Tu m'écoutes ?",""]],"traps":[["Estoy en tren de trabajar.","Estoy trabajando.","« En train de » ne se traduit pas mot à mot."],["Está leiendo.","Está leyendo.","Entre deux voyelles, le i devient y."],["Están dormiendo.","Están durmiendo.","Dormir change son o en u au gérondif."]],"tip":"Être en train de, c'est estar + -ando ou -iendo."},
"es_pronombres_cd":{"intro":"Pour ne pas répéter « le livre, le livre », on le remplace par un petit pronom. En espagnol, lo, la, los, las font ce travail, et leur place suit une règle simple.","parts":[{"h":"Les formes","p":"Le pronom prend le genre et le nombre du nom espagnol qu'il remplace.\n\nPour les personnes, me, te, nos marchent comme me, te, nous en français.","rows":[["lo","¿El libro? Lo tengo.","masculin singulier"],["la","¿La llave? La tengo.","féminin singulier"],["los","¿Los billetes? Los tengo.","masculin pluriel"],["las","¿Las llaves? Las tengo.","féminin pluriel"],["me, te, nos","Te llamo mañana.","comme en français"],["os","Os veo luego.","vous, en Espagne"]]},{"h":"Devant le verbe conjugué","p":"Avec un verbe conjugué, le pronom se met devant, comme en français : lo compré, la veo.\n\nLa négation no se place devant le pronom : no lo sé, no las encuentro."},{"h":"Collé à la fin","p":"Avec un infinitif, un gérondif ou un impératif affirmatif, le pronom se colle à la fin du verbe : quiero verla, estoy leyéndolo, cómpralo.\n\nAvec un infinitif après un verbe conjugué, tu peux aussi le mettre devant : la quiero ver. Les deux sont corrects."},{"h":"Lo pour une idée","p":"Lo remplace aussi une idée entière, comme « le » en français dans « je le sais » : ya lo sé, no lo creo."}],"ex":[["¿El libro? Lo compré ayer.","Le livre ? Je l'ai acheté hier.",""],["¿Las llaves? No las encuentro.","Les clés ? Je ne les trouve pas.",""],["Te llamo mañana.","Je t'appelle demain.",""],["Quiero verla esta tarde.","Je veux la voir cet après-midi.","collé à l'infinitif"],["¿Y los tomates? Cómpralos en el mercado.","Et les tomates ? Achète-les au marché.","impératif : collé, avec un accent"],["Ya lo sé.","Je le sais déjà.","lo pour une idée"],["La película es muy buena, la vi el sábado.","Le film est très bon, je l'ai vu samedi.","película est féminin : la"],["¿Me ayudas?","Tu m'aides ?",""]],"traps":[["Compré lo ayer.","Lo compré ayer.","Avec un verbe conjugué, le pronom se met devant."],["Quiero la ver.","Quiero verla.","Le pronom se colle à l'infinitif, ou se met devant quiero."],["¿La película? Lo vi ayer.","¿La película? La vi ayer.","Le pronom prend le genre du mot espagnol, pas du mot français."]],"tip":"Devant le verbe conjugué, collé derrière l'infinitif : lo compro, quiero comprarlo."},
"es_indef_imperf":{"intro":"Quand tu racontes une histoire, il y a le décor et il y a ce qui arrive. L'espagnol sépare les deux avec deux temps, comme l'imparfait et le passé composé en français.","parts":[{"h":"Le décor et l'événement","p":"L'imperfecto pose la scène : ce qui était en cours, la description, l'habitude. Leía, llovía, había mucha gente.\n\nL'indefinido fait avancer l'histoire : une action qui arrive et se termine. Sonó el teléfono, llegué, nos quedamos.","rows":[["imperfecto","Leía…","ce qui était en cours"],["indefinido","… cuando sonó el teléfono.","ce qui arrive"],["imperfecto","Hacía sol.","description"],["indefinido","Fuimos a la playa.","action terminée"]]},{"h":"Ton instinct de francophone","p":"Bonne nouvelle : tu as déjà ce réflexe. Là où tu dirais « je lisais », mets l'imperfecto. Là où tu dirais « le téléphone a sonné », mets l'indefinido.\n\nPour une action en cours, estaba + gérondif est aussi très courant : estaba leyendo veut dire leía."},{"h":"Les cas qui trompent","p":"Une action longue mais terminée reste à l'indefinido : viví diez años en Barcelona. Ce qui compte, c'est qu'on la voie comme finie.\n\nMême logique pour « il y avait » : no había nadie décrit la scène, hubo un accidente raconte un événement."}],"ex":[["Leía cuando sonó el teléfono.","Je lisais quand le téléphone a sonné.",""],["Llovía, así que nos quedamos en casa.","Il pleuvait, alors nous sommes restés à la maison.",""],["Cuando llegué, no había nadie.","Quand je suis arrivé, il n'y avait personne.","décor : había"],["Estaba durmiendo cuando me llamaste.","Je dormais quand tu m'as appelé.","action en cours"],["Era tarde y estábamos cansados, pero terminamos el trabajo.","Il était tard et nous étions fatigués, mais nous avons fini le travail.",""],["Viví diez años en Barcelona.","J'ai vécu dix ans à Barcelone.","longue mais terminée"],["De niña, pasaba los veranos en el pueblo.","Petite, je passais les étés au village.","habitude"],["Ayer hubo un accidente en la autopista.","Hier, il y a eu un accident sur l'autoroute.","événement : hubo"]],"traps":[["Leí cuando sonaba el teléfono.","Leía cuando sonó el teléfono.","Ce qui est en cours va à l'imperfecto, ce qui arrive à l'indefinido."],["Vivía diez años en Barcelona.","Viví diez años en Barcelona.","Une durée fermée et terminée prend l'indefinido."],["Cuando llegué, no hubo nadie.","Cuando llegué, no había nadie.","Décrire la scène, c'est l'imperfecto : había."]],"tip":"Imperfecto pour le décor, indefinido pour ce qui arrive : leía cuando sonó."},
"es_perfecto":{"intro":"« Tu es déjà allé au Mexique ? », « J'ai bu deux cafés ce matin » : le pretérito perfecto relie le passé au moment présent. En Espagne, on l'entend tout le temps.","parts":[{"h":"La forme","p":"On prend haber au présent, puis le participe passé. Le participe ne s'accorde jamais, et rien ne se glisse entre haber et lui.","rows":[["yo","he comido",""],["tú","has comido",""],["él, ella, usted","ha comido",""],["nosotros","hemos comido",""],["vosotros","habéis comido","en Espagne"],["ellos, ustedes","han comido",""]]},{"h":"Le participe","p":"Les verbes en -ar donnent -ado, ceux en -er et -ir donnent -ido : hablado, comido, vivido. Quelques irréguliers sont très fréquents.","rows":[["hacer","hecho",""],["decir","dicho",""],["ver","visto",""],["escribir","escrito",""],["poner","puesto",""],["volver","vuelto",""]]},{"h":"Quand l'utiliser","p":"En Espagne, le perfecto sert pour une action dans une période pas encore finie : hoy, esta mañana, esta semana, este año. Et pour une expérience sans date : nunca, ya, todavía no, alguna vez.\n\nAvec ayer, el lunes ou une date précise, on passe à l'indefinido : ayer comí tarde, mais hoy he comido tarde."},{"h":"Espagne, Amérique latine et français","p":"En Amérique latine, l'indefinido remplace souvent le perfecto : hoy comí tarde, ¿ya comiste? Les deux usages sont corrects.\n\nAttention au réflexe français : « je suis allé » se dit he ido. L'auxiliaire est toujours haber, jamais ser."}],"ex":[["Nunca he estado en México.","Je ne suis jamais allé au Mexique.","expérience sans date"],["Esta mañana he tomado dos cafés.","Ce matin, j'ai bu deux cafés.","période pas finie"],["¿Alguna vez has comido churros?","Tu as déjà mangé des churros ?",""],["Todavía no he terminado.","Je n'ai pas encore fini.",""],["Hoy he comido muy tarde.","Aujourd'hui, j'ai mangé très tard.",""],["¿Has visto mis gafas?","Tu as vu mes lunettes ?","ver : visto"],["Mis padres han vuelto de vacaciones.","Mes parents sont rentrés de vacances.","haber, pas ser"],["Esta semana he hecho mucho deporte.","Cette semaine, j'ai fait beaucoup de sport.","hacer : hecho"]],"traps":[["Ayer he comido tarde.","Ayer comí tarde.","Avec ayer, on emploie l'indefinido."],["Soy ido al cine.","He ido al cine.","L'auxiliaire est toujours haber, même là où le français dit « être »."],["He todavía no terminado.","Todavía no he terminado.","Rien ne se met entre haber et le participe."]],"tip":"Hoy, ya, nunca : he comido ; ayer : comí."},
"es_por_para":{"intro":"Remercier quelqu'un, offrir un cadeau, dire pourquoi tu travailles : le français dit « pour » partout. L'espagnol choisit entre por et para, selon le sens.","parts":[{"h":"Para : vers un but","p":"Para regarde en avant : vers un but, une personne qui reçoit, une destination ou une date limite.\n\nSi tu peux dire « afin de » ou « destiné à », c'est para.","rows":[["but","Trabajo para ganar dinero.","afin de"],["destinataire","Este regalo es para ti.","destiné à"],["destination","Salgo para Madrid.","en direction de"],["date limite","Es para el lunes.","pour lundi au plus tard"]]},{"h":"Por : la cause et le chemin","p":"Por regarde en arrière ou autour : la cause, ce qu'on donne en échange, le lieu par où on passe, le moyen.\n\nSi tu peux dire « à cause de », « en échange de » ou « par », c'est por.","rows":[["cause","Gracias por tu ayuda.","à cause de, grâce à"],["échange","Lo compré por cien euros.","en échange de"],["passage","Paseamos por el parque.","à travers"],["moyen","Te llamo por teléfono.","par"],["moment de la journée","Trabajo por la mañana.","le matin"]]},{"h":"Une même phrase, deux sens","p":"Parfois les deux sont possibles, mais le sens change. Lo hago para ti : je le fais pour te l'offrir. Lo hago por ti : je le fais pour toi, par affection ou à ta place.\n\nEt quelques expressions figées prennent toujours por : por favor, por fin, por ejemplo, por eso."}],"ex":[["Gracias por tu ayuda.","Merci pour ton aide.","cause : por"],["Este regalo es para ti.","Ce cadeau est pour toi.","destinataire : para"],["Trabajo para ganar dinero.","Je travaille pour gagner de l'argent.","but : para"],["Compré esta bici por cien euros.","J'ai acheté ce vélo pour cent euros.","échange : por"],["Paseamos por el centro.","Nous nous promenons dans le centre.","passage : por"],["El informe es para el viernes.","Le rapport est pour vendredi.","date limite : para"],["El vuelo para Lima sale a las seis.","Le vol pour Lima part à six heures.","destination : para"],["Llegué tarde por el tráfico.","Je suis arrivé en retard à cause de la circulation.","cause : por"]],"traps":[["Gracias para todo.","Gracias por todo.","On remercie à cause de quelque chose : por."],["Estudio por aprobar el examen.","Estudio para aprobar el examen.","Un but, « afin de », prend para."],["Lo compré para diez euros.","Lo compré por diez euros.","Un prix est un échange : por."]],"tip":"Para vise un but, por explique une cause ou un échange."},
"es_subj_deseo":{"intro":"Demander à un ami de venir, espérer qu'il fasse beau, expliquer pourquoi tu dis quelque chose : l'espagnol utilise alors le subjonctif. Tu le connais déjà en français : « je veux que tu viennes ».","parts":[{"h":"Former le subjonctif présent","p":"Pars du yo du présent, enlève le -o, et prends la voyelle « opposée » : les verbes en -ar prennent e, ceux en -er et -ir prennent a.\n\nAinsi, l'irrégularité du yo se garde partout : tengo donne tenga, vengo donne venga, hago donne haga.","rows":[["hablar (hablo)","hable, hables, hable, hablemos, hablen",""],["comer (como)","coma, comas, coma, comamos, coman",""],["venir (vengo)","venga, vengas, venga, vengamos, vengan",""],["hacer (hago)","haga, hagas, haga, hagamos, hagan",""],["saber","sepa, sepas, sepa, sepamos, sepan","irrégulier"],["ser / ir","sea, seas… / vaya, vayas…","irréguliers"]]},{"h":"Deux sujets : subjonctif","p":"Quand tu veux que quelqu'un d'autre fasse quelque chose, il y a deux sujets différents. Le second verbe passe au subjonctif : quiero que vengas.\n\nSi c'est la même personne, on garde l'infinitif, comme en français. Même règle avec para que.","rows":[["même sujet","Quiero venir.","je veux venir"],["deux sujets","Quiero que vengas.","je veux que tu viennes"],["même sujet","Lo digo para ayudar.","pour aider"],["deux sujets","Lo digo para que lo sepas.","pour que tu le saches"]]},{"h":"Ojalá","p":"Ojalá exprime un souhait : pourvu que, j'espère que. Il est toujours suivi du subjonctif, avec ou sans que.\n\nC'est un mot très vivant à l'oral. Tout seul, ¡ojalá! veut dire « j'espère bien »."}],"ex":[["Quiero que vengas a mi cumpleaños.","Je veux que tu viennes à mon anniversaire.",""],["¡Ojalá haga buen tiempo mañana!","Pourvu qu'il fasse beau demain !",""],["Te lo digo para que lo sepas.","Je te le dis pour que tu le saches.","saber : sepa"],["Mi madre quiere que la llame.","Ma mère veut que je l'appelle.",""],["Quiero aprender a cocinar.","Je veux apprendre à cuisiner.","même sujet : infinitif"],["Hablo despacio para que me entiendas.","Je parle lentement pour que tu me comprennes.",""],["Ojalá no llueva el sábado.","Pourvu qu'il ne pleuve pas samedi.",""],["Mis padres quieren que estudie medicina.","Mes parents veulent que j'étudie la médecine.",""]],"traps":[["Quiero que vienes.","Quiero que vengas.","Après querer que, le verbe passe au subjonctif."],["Quiero que yo vaya.","Quiero ir.","Même sujet : on garde l'infinitif."],["Ojalá hace buen tiempo.","Ojalá haga buen tiempo.","Ojalá est toujours suivi du subjonctif."]],"tip":"Deux personnes, un que, un subjonctif : quiero que vengas."},
"es_futuro":{"intro":"Faire une promesse, annoncer un plan, imaginer demain : le futur simple sert à tout ça. C'est un des temps les plus réguliers de l'espagnol.","parts":[{"h":"Infinitif + terminaison","p":"Comme en français, on garde l'infinitif entier et on ajoute la terminaison. Elle est la même pour -ar, -er et -ir.\n\nToutes les formes ont un accent, sauf nosotros : hablaré, hablarás, mais hablaremos.","rows":[["yo","hablaré",""],["tú","hablarás",""],["él, ella, usted","hablará",""],["nosotros","hablaremos","sans accent"],["vosotros","hablaréis",""],["ellos, ustedes","hablarán",""]]},{"h":"Les radicaux irréguliers","p":"Quelques verbes très courants changent de radical, mais gardent les mêmes terminaisons. Ces radicaux serviront aussi au conditionnel.","rows":[["tener","tendré",""],["salir","saldré","partir, sortir"],["venir","vendré",""],["poder","podré",""],["poner","pondré",""],["saber","sabré",""],["hacer","haré",""],["decir","diré",""]]},{"h":"Futur, ir a, et le piège du si","p":"À l'oral, ir a + infinitif est souvent plus naturel pour un projet proche. Le futur simple sonne plutôt comme une promesse ou une prévision.\n\nEt comme en français, jamais de futur après si : si llueve, me quedaré en casa. Le présent suit si, le futur vient ensuite."}],"ex":[["Mañana tendré más tiempo.","Demain, j'aurai plus de temps.",""],["Saldremos a las ocho.","Nous partirons à huit heures.","salir : saldr-"],["¿Vendrás a la fiesta?","Tu viendras à la fête ?",""],["Te lo diré.","Je te le dirai.","decir : dir-"],["Si llueve, me quedaré en casa.","S'il pleut, je resterai à la maison.","présent après si"],["El año que viene viviremos en Valencia.","L'année prochaine, nous habiterons à Valence.",""],["No te preocupes, lo haré esta tarde.","Ne t'inquiète pas, je le ferai cet après-midi.","une promesse"],["¿Podrás ayudarme el lunes?","Tu pourras m'aider lundi ?",""]],"traps":[["Si lloverá, me quedaré en casa.","Si llueve, me quedaré en casa.","Après si, on met le présent, jamais le futur."],["Teneré más tiempo.","Tendré más tiempo.","Tener a un radical irrégulier au futur : tendr-."],["Hablarémos mañana.","Hablaremos mañana.","À nosotros, pas d'accent au futur."]],"tip":"Infinitif + é, ás, á : hablaré, et quelques radicaux à part comme tendré, haré, diré."},
"es_condicional":{"intro":"Demander un service poliment, rêver d'un voyage, conseiller un ami : le conditionnel adoucit tout. C'est le temps de la politesse et du « à ta place ».","parts":[{"h":"La forme","p":"Le conditionnel se forme comme le futur : l'infinitif entier, plus une terminaison. Ici, c'est -ía, comme l'imperfecto des verbes en -er.\n\nToutes les formes portent un accent sur le í.","rows":[["yo","hablaría",""],["tú","hablarías",""],["él, ella, usted","hablaría","comme yo"],["nosotros","hablaríamos",""],["vosotros","hablaríais",""],["ellos, ustedes","hablarían",""]]},{"h":"Les mêmes irréguliers que le futur","p":"Si tu connais tendré, tu connais tendría : le radical est le même, seule la terminaison change.","rows":[["tener","tendría","futur : tendré"],["hacer","haría","futur : haré"],["poder","podría","futur : podré"],["decir","diría","futur : diré"],["salir","saldría","futur : saldré"]]},{"h":"Adoucir, souhaiter, conseiller","p":"Pour une demande polie, le conditionnel remplace le présent : ¿podrías ayudarme? est plus doux que ¿puedes ayudarme?\n\nPour un souhait, me gustaría marche comme gustar. Pour un conseil, on dit yo en tu lugar ou yo que tú, puis le conditionnel : yo que tú, no diría nada."}],"ex":[["Me gustaría viajar a Perú.","J'aimerais voyager au Pérou.","un souhait"],["¿Podrías ayudarme con la maleta?","Tu pourrais m'aider avec la valise ?","demande polie"],["Yo en tu lugar, no diría nada.","À ta place, je ne dirais rien.","un conseil"],["¿Te gustaría venir con nosotros?","Ça te dirait de venir avec nous ?","une invitation"],["Yo que tú, hablaría con ella.","Si j'étais toi, je lui parlerais.",""],["Con más dinero, tendríamos una casa en la playa.","Avec plus d'argent, nous aurions une maison au bord de la mer.","tener : tendr-"],["¿Me podría traer la cuenta, por favor?","Pourriez-vous m'apporter l'addition, s'il vous plaît ?","usted : le vouvoiement"],["Sería genial verte pronto.","Ce serait génial de te voir bientôt.",""]],"traps":[["Yo en tu lugar, no diré nada.","Yo en tu lugar, no diría nada.","Un conseil imaginé prend le conditionnel, pas le futur."],["Teneríamos más tiempo.","Tendríamos más tiempo.","Le conditionnel garde le radical irrégulier du futur : tendr-."],["¿Podrías me ayudar?","¿Podrías ayudarme?","Le pronom se colle à l'infinitif, ou se met devant podrías."]],"tip":"Futur en é, conditionnel en ía : tendré, tendría ; et pour être poli, podrías."},
"es_imperativo":{"intro":"Pour donner un conseil, une consigne ou un ordre à un ami : « viens », « assieds-toi », « ne t'inquiète pas ». En espagnol, l'affirmatif et le négatif ne se forment pas de la même façon.","parts":[{"h":"L'affirmatif avec tú","p":"Pour tutoyer, prends le présent à la 3e personne du singulier : él habla donne habla. Pas besoin d'apprendre une nouvelle forme.\n\nHuit verbes très courants sont irréguliers. Apprends-les par cœur, ils servent tous les jours.","rows":[["hablar","¡Habla más alto!","comme él habla"],["comer","¡Come algo!","comme él come"],["venir","¡Ven aquí!","irrégulier : ven"],["tener","¡Ten cuidado!","irrégulier : ten"],["poner","¡Pon la mesa!","irrégulier : pon"],["salir","¡Sal de ahí!","irrégulier : sal"],["hacer","¡Haz los deberes!","irrégulier : haz"],["decir / ir","¡Di la verdad! ¡Ve a casa!","irréguliers : di, ve"]]},{"h":"Le négatif : on passe au subjonctif","p":"Au négatif, l'espagnol change de forme : no + subjonctif présent. Les verbes en -ar prennent un e, les verbes en -er et -ir prennent un a.\n\nLes irréguliers partent de la 1re personne du présent : tengo donne no tengas, hago donne no hagas.","rows":[["hablar","No hables tan alto.","-ar : e"],["comer","No comas tan rápido.","-er : a"],["escribir","No escribas en el libro.","-ir : a"],["venir","No vengas tarde.","de vengo"],["hacer","No hagas ruido.","de hago"],["ir","No vayas solo.","irrégulier"]]},{"h":"La place des pronoms","p":"À l'affirmatif, les pronoms se collent à la fin du verbe : siéntate, dímelo. On ajoute souvent un accent écrit pour garder la bonne syllabe accentuée.\n\nAu négatif, ils passent devant le verbe, comme en français : no te preocupes, no me lo digas.","rows":[["sentarse","Siéntate. / No te sientes.","accent écrit à l'affirmatif"],["levantarse","Levántate. / No te levantes.",""],["decir + me + lo","Dímelo. / No me lo digas.","deux pronoms"]]}],"ex":[["¡Ven aquí, que te enseño una cosa!","Viens ici, je vais te montrer quelque chose !",""],["No te preocupes, todo va a salir bien.","Ne t'inquiète pas, tout va bien se passer.",""],["Siéntate, por favor.","Assieds-toi, s'il te plaît.","pronom collé, accent écrit"],["Ten cuidado con el perro.","Fais attention au chien.","tener : ten"],["No comas tan rápido.","Ne mange pas si vite.","subjonctif au négatif"],["Dime la verdad.","Dis-moi la vérité.","di + me"],["No hagas ruido, el bebé está durmiendo.","Ne fais pas de bruit, le bébé dort.","de hago"],["Pon la mesa, que vamos a cenar.","Mets la table, on va dîner.",""]],"traps":[["No habla tan alto.","No hables tan alto.","Au négatif, on prend le subjonctif, pas le présent."],["No preocúpate.","No te preocupes.","Au négatif, le pronom passe devant et le verbe va au subjonctif."],["Hace los deberes.","Haz los deberes.","Hacer est irrégulier à l'impératif : haz."]],"tip":"Pour dire oui, prends le présent (habla) ; pour dire non, prends le subjonctif (no hables)."},
"es_subj_emocion":{"intro":"Dire ce que tu ressens face à une situation, ou exprimer un doute : « je suis content que tu sois là », « je ne crois pas qu'il vienne ». Comme en français, ces phrases appellent le subjonctif.","parts":[{"h":"Émotion + que + subjonctif","p":"Quand la phrase principale exprime un sentiment, le verbe qui suit est au subjonctif. C'est la même logique qu'en français.\n\nAttention à la construction : me alegro de que, avec de, mais me alegra que, sans de. Les deux sont corrects.","rows":[["me alegro de que","Me alegro de que estés aquí.","je suis content que"],["me alegra que","Me alegra que vengas.","même sens, sans de"],["me molesta que","Me molesta que llegue tarde.","ça m'énerve que"],["me da miedo que","Me da miedo que se pierda.","j'ai peur que"],["siento que","Siento que no puedas venir.","je regrette que"]]},{"h":"Doute + que + subjonctif","p":"Quand tu doutes, ou que tu présentes une chose comme seulement possible, tu mets aussi le subjonctif.\n\nPuede que est très fréquent à l'oral : puede que llueva veut dire « il se peut qu'il pleuve ».","rows":[["no creo que","No creo que venga.","je ne crois pas que"],["dudo que","Dudo que sea verdad.","je doute que"],["es posible que","Es posible que llueva.","il est possible que"],["puede que","Puede que llegue tarde.","il se peut que"]]},{"h":"Le piège : creo que / no creo que","p":"Creo que, pienso que et me parece que présentent une chose comme vraie. Ils prennent donc l'indicatif : creo que viene.\n\nÀ la négative, la chose devient douteuse et le subjonctif arrive : no creo que venga. Le français fait pareil : « je crois qu'il vient », « je ne crois pas qu'il vienne ».","rows":[["creo que + indicatif","Creo que tiene razón.","tu affirmes"],["no creo que + subjonctif","No creo que tenga razón.","tu doutes"],["es verdad que + indicatif","Es verdad que es caro.","un fait"],["no es verdad que + subjonctif","No es verdad que sea caro.","un fait nié"]]}],"ex":[["Me alegro de que estés aquí.","Je suis content que tu sois là.",""],["Me molesta que siempre llegue tarde.","Ça m'énerve qu'il arrive toujours en retard.",""],["No creo que venga esta noche.","Je ne crois pas qu'il vienne ce soir.",""],["Es posible que llueva mañana.","Il est possible qu'il pleuve demain.",""],["Creo que el museo cierra a las seis.","Je crois que le musée ferme à six heures.","creo que : indicatif"],["Me da pena que te vayas tan pronto.","Ça me fait de la peine que tu partes si tôt.",""],["Dudo que encuentre entradas para el concierto.","Je doute qu'il trouve des billets pour le concert.",""],["Puede que tengas razón.","Il se peut que tu aies raison.",""]],"traps":[["No creo que viene.","No creo que venga.","Après no creo que, le doute impose le subjonctif."],["Creo que venga.","Creo que viene.","Creo que affirme quelque chose : il prend l'indicatif."],["Espero que vienes.","Espero que vengas.","Esperar que prend le subjonctif, alors que « espérer que » prend l'indicatif."]],"tip":"Je ressens ou je doute : subjonctif. J'affirme : indicatif."},
"es_pluscuamperfecto":{"intro":"Raconter une histoire où une chose s'était déjà passée avant une autre : « quand je suis arrivé, elle était déjà partie ». L'espagnol a le même temps que le français.","parts":[{"h":"La forme","p":"On prend haber à l'imparfait, puis le participe passé. Le participe ne change jamais : il ne s'accorde ni avec le sujet ni avec l'objet.\n\nEn espagnol, tous les verbes utilisent haber, même ir, salir ou llegar. Jamais « être » comme en français.","rows":[["yo","había comido","j'avais mangé"],["tú","habías llegado","tu étais arrivé"],["él / ella / usted","había salido","il était sorti"],["nosotros","habíamos visto","nous avions vu"],["vosotros","habíais hecho","vous aviez fait"],["ellos / ustedes","habían dicho","ils avaient dit"]]},{"h":"Quand l'utiliser","p":"Le plus-que-parfait marque une action terminée avant un autre moment du passé. Souvent, l'autre action est au passé simple (pretérito) : cuando llegué, ya se había ido.\n\nYa (déjà) et nunca (jamais) l'accompagnent souvent : nunca había visto el mar."},{"h":"Les participes irréguliers","p":"Les participes réguliers finissent en -ado pour les verbes en -ar, en -ido pour les verbes en -er et -ir. Quelques verbes fréquents font exception.","rows":[["hacer","hecho","fait"],["ver","visto","vu"],["decir","dicho","dit"],["escribir","escrito","écrit"],["poner","puesto","mis"],["volver","vuelto","revenu"],["abrir","abierto","ouvert"],["romper","roto","cassé"]]},{"h":"La place des mots","p":"On ne sépare jamais había du participe. Les pronoms et la négation se placent devant había : ya se había ido, no lo había visto.\n\nYa se met en général devant : ya habían comido."}],"ex":[["Cuando llegué, ya se había ido.","Quand je suis arrivé, elle était déjà partie.",""],["Nunca había visto el mar.","Je n'avais jamais vu la mer.",""],["Cuando llamamos, ya habían comido.","Quand on a appelé, ils avaient déjà mangé.",""],["No sabía que habías vuelto.","Je ne savais pas que tu étais rentré.","haber, même avec volver"],["Me dijo que había perdido las llaves.","Il m'a dit qu'il avait perdu ses clés.",""],["El tren ya había salido cuando llegamos a la estación.","Le train était déjà parti quand nous sommes arrivés à la gare.",""],["¿Habías estado antes en México?","Tu étais déjà allé au Mexique avant ?",""]],"traps":[["Cuando llegué, ella ya estaba salida.","Cuando llegué, ella ya había salido.","Pour « elle était partie », toujours haber, jamais estar ni ser."],["Las había vistas.","Las había visto.","Le participe ne s'accorde jamais avec haber."],["Había ya comido.","Ya había comido.","On ne coupe pas había et le participe."]],"tip":"Avant un autre passé : había + participe, et haber pour tous les verbes."},
"es_si_imperfecto":{"intro":"Rêver tout haut : « si j'avais le temps, je voyagerais », « si j'étais toi… ». C'est l'hypothèse irréelle : elle ne correspond pas à la réalité d'aujourd'hui.","parts":[{"h":"La structure","p":"Après si, l'espagnol met le subjonctif imparfait, là où le français met l'imparfait. Dans l'autre partie, on met le conditionnel, comme en français.\n\nL'ordre peut s'inverser : viajaría si tuviera tiempo.","rows":[["si + subjonctif imparfait","si tuviera tiempo","si j'avais le temps"],["conditionnel","viajaría más","je voyagerais plus"]]},{"h":"Former le subjonctif imparfait","p":"Prends le passé simple (pretérito) à la 3e personne du pluriel, enlève -ron et ajoute -ra : tuvieron donne tuviera, fueron donne fuera. Avec nosotros, un accent apparaît : tuviéramos.\n\nIl existe une deuxième forme en -se : tuviese, fuese. Elle a le même sens, elle est juste un peu plus écrite.","rows":[["tener","tuvieron","tuviera / tuviese"],["ser / ir","fueron","fuera / fuese"],["hacer","hicieron","hiciera / hiciese"],["poder","pudieron","pudiera / pudiese"],["hablar","hablaron","hablara / hablase"],["ganar","ganaron","ganara / ganase"]]},{"h":"Le piège : pas de conditionnel après si","p":"Le français ne dit pas « si j'aurais ». L'espagnol non plus : « si tendría » est faux. Après si, jamais de conditionnel.\n\nAutre piège : l'imparfait de l'indicatif. Si tenía tiempo existe, mais il parle d'une habitude passée (« quand j'avais le temps »), pas d'une hypothèse."}],"ex":[["Si tuviera más tiempo, viajaría más.","Si j'avais plus de temps, je voyagerais plus.",""],["¿Qué harías si te tocara la lotería?","Qu'est-ce que tu ferais si tu gagnais au loto ?","tocar : être gagné, à un jeu"],["Si yo fuera tú, lo llamaría.","Si j'étais toi, je l'appellerais.","fuera : de ser"],["Si viviéramos cerca del mar, nadaríamos todos los días.","Si on habitait près de la mer, on nagerait tous les jours.",""],["Si hiciera buen tiempo, comeríamos fuera.","S'il faisait beau, on mangerait dehors.",""],["Me compraría ese coche si pudiera.","Je m'achèterais cette voiture si je pouvais.","ordre inversé"],["Si supieras cocinar, no comerías pizza todas las noches.","Si tu savais cuisiner, tu ne mangerais pas de pizza tous les soirs.",""]],"traps":[["Si tendría tiempo, viajaría.","Si tuviera tiempo, viajaría.","Jamais de conditionnel après si."],["Si tenía dinero, compraría una casa.","Si tuviera dinero, compraría una casa.","Pour une hypothèse, c'est le subjonctif imparfait, pas l'imparfait."],["Si fuera tú, lo llamaré.","Si fuera tú, lo llamaría.","Le résultat d'une hypothèse irréelle se met au conditionnel."]],"tip":"Si + -ra, puis -ría : si tuviera, viajaría."},
"es_estilo_indirecto":{"intro":"Rapporter ce que quelqu'un a dit : « il m'a dit qu'il était fatigué », « elle m'a demandé où j'habitais ». Comme en français, les temps reculent d'un cran.","parts":[{"h":"Reculer les temps","p":"Quand le verbe qui introduit est au passé (dijo, me contó), le verbe rapporté recule, exactement comme en français.\n\nSi le verbe qui introduit est au présent, rien ne bouge : dice que está cansado.","rows":[["estoy cansado","Dijo que estaba cansado.","présent devient imparfait"],["vendré","Dijo que vendría.","futur devient conditionnel"],["perdí el tren","Dijo que había perdido el tren.","passé devient plus-que-parfait"],["he terminado","Dijo que había terminado.","idem"]]},{"h":"Les questions rapportées","p":"Une question avec un mot interrogatif le garde, avec son accent écrit : me preguntó dónde vivía.\n\nUne question fermée, à laquelle on répond oui ou non, est introduite par si, sans accent : me preguntó si tenía hambre.","rows":[["¿Dónde vives?","Me preguntó dónde vivía.","accent gardé"],["¿Qué quieres?","Me preguntó qué quería.",""],["¿Tienes hambre?","Me preguntó si tenía hambre.","si sans accent"]]},{"h":"Les ordres et les demandes","p":"Un ordre ou une demande rapportés passent au subjonctif imparfait après que. Le français, lui, dit souvent de + infinitif : « elle m'a demandé de l'aider ».\n\nPour une demande, c'est pedir, pas preguntar. Preguntar sert seulement pour une question.","rows":[["Ayúdame.","Me pidió que la ayudara.","demande"],["Ven pronto.","Me dijo que viniera pronto.","ordre"],["No te preocupes.","Me dijo que no me preocupara.","ordre négatif"]]}],"ex":[["Me dijo que estaba cansado.","Il m'a dit qu'il était fatigué.",""],["Me preguntó dónde vivía.","Elle m'a demandé où j'habitais.",""],["Dijo que vendría a la fiesta.","Il a dit qu'il viendrait à la fête.","vendré devient vendría"],["Me pidió que la ayudara con la mudanza.","Elle m'a demandé de l'aider pour le déménagement.","pedir que + subjonctif"],["Nos contó que había vivido en Perú.","Il nous a raconté qu'il avait vécu au Pérou.",""],["Le pregunté si quería un café.","Je lui ai demandé s'il voulait un café.",""],["Mi madre me dijo que llamara al médico.","Ma mère m'a dit d'appeler le médecin.","un ordre : subjonctif"]],"traps":[["Me preguntó de ayudarla.","Me pidió que la ayudara.","Demander un service, c'est pedir ; preguntar sert pour une question."],["Me preguntó donde vivía.","Me preguntó dónde vivía.","Le mot interrogatif garde son accent dans une question rapportée."],["Me dijo de venir pronto.","Me dijo que viniera pronto.","Un ordre rapporté se construit avec que + subjonctif."]],"tip":"On rapporte : on recule d'un cran. On rapporte un ordre : on passe au subjonctif."},
"es_pasiva_se":{"intro":"Les panneaux, les recettes, les règles : « ici, on parle espagnol », « appartements à vendre ». Quand on ne dit pas qui fait l'action, l'espagnol utilise très souvent se.","parts":[{"h":"Se pour dire « on »","p":"Pour une action faite par les gens en général, on met se devant le verbe à la 3e personne : aquí se habla español.\n\nC'est la tournure la plus naturelle. Uno et la gente existent aussi, mais se est bien plus fréquent."},{"h":"L'accord avec la chose","p":"Le verbe s'accorde avec la chose dont on parle. Une chose : singulier. Plusieurs choses : pluriel.\n\nC'est ce que tu lis sur les vitrines et les annonces : se vende piso, se venden pisos.","rows":[["se + verbe au singulier","Se vende piso.","une chose"],["se + verbe au pluriel","Se venden pisos.","plusieurs choses"],["se + verbe au singulier","Se alquila habitación.","chambre à louer"],["se + verbe au pluriel","Se necesitan camareros.","on cherche des serveurs"]]},{"h":"Le vrai passif : ser + participe","p":"Il existe aussi un passif comme en français : ser + participe, et le participe s'accorde. El puente fue construido en 1900.\n\nIl sonne écrit, presque journalistique. À l'oral, on dit plutôt se construyó. Pour nommer l'auteur, on ajoute por : fue pintado por Goya.","rows":[["ser + participe","El puente fue construido en 1900.","écrit"],["se + verbe","El puente se construyó en 1900.","plus naturel"],["ser + participe + por","El cuadro fue pintado por Goya.","on nomme l'auteur"]]}],"ex":[["Aquí se habla español.","Ici, on parle espagnol.",""],["Se venden pisos en el centro.","Appartements à vendre dans le centre.","pluriel : se venden"],["¿Cómo se escribe tu apellido?","Comment s'écrit ton nom de famille ?",""],["En esta tienda se aceptan tarjetas.","Dans ce magasin, on accepte les cartes.",""],["El puente se construyó en 1900.","Le pont a été construit en 1900.",""],["La novela fue traducida a treinta idiomas.","Le roman a été traduit en trente langues.","passif écrit"],["No se puede fumar aquí.","On ne peut pas fumer ici.",""],["En España se cena muy tarde.","En Espagne, on dîne très tard.",""]],"traps":[["Se vende pisos.","Se venden pisos.","Le verbe s'accorde avec la chose : plusieurs pisos, verbe au pluriel."],["Aquí es hablado español.","Aquí se habla español.","Pour « on », l'espagnol prend se, pas le passif avec ser."],["El cuadro fue pintado de Goya.","El cuadro fue pintado por Goya.","L'auteur d'un passif s'introduit avec por, pas de."]],"tip":"Pas de « on » en espagnol : un se, et le verbe s'accorde avec la chose."},
"es_relativos":{"intro":"Pour relier deux idées sans te répéter : « la ville où je suis né », « l'ami avec qui je voyage », « le livre dont je t'ai parlé ». L'espagnol a ses propres outils, et pas de « dont ».","parts":[{"h":"Que, le relatif à tout faire","p":"Que traduit à la fois « qui » et « que » : la chica que vive aquí, la película que vimos. Il marche pour les personnes et pour les choses.\n\nSans préposition, on ne met pas quien. On dit el chico que vino, pas el chico quien vino.","rows":[["qui","La chica que vive aquí es chilena.","que sujet"],["que","La película que vimos era larga.","que objet"]]},{"h":"Après une préposition","p":"Après con, de, en, para ou por, on met el que, la que, los que ou las que, accordé avec le nom. Pour une personne, quien marche aussi.\n\nL'article compte : il dit de qui ou de quoi on parle.","rows":[["con el que / con quien","El amigo con el que viajo.","avec qui"],["para la que","La empresa para la que trabajo.","pour laquelle"],["en el que / donde","La ciudad en la que nací.","où"],["de los que","Los libros de los que hablamos.","dont"]]},{"h":"Où, ce que, dont","p":"Où se dit donde ou en el que. Ce que se dit lo que : lo que quiero es dormir.\n\n« Dont » n'existe pas. Regarde le verbe : on dit hablar de, donc el libro del que te hablé.","rows":[["où","La ciudad donde nací.","ou en la que"],["ce que","Lo que quiero es dormir.","lo : neutre"],["dont","El libro del que te hablé.","de hablar de"]]}],"ex":[["La chica con la que hablé es chilena.","La fille avec qui j'ai parlé est chilienne.",""],["Lo que quiero es dormir.","Ce que je veux, c'est dormir.",""],["La ciudad donde nací es pequeña.","La ville où je suis né est petite.",""],["El amigo con quien viajo es chileno.","L'ami avec qui je voyage est chilien.","quien : une personne"],["El libro del que te hablé está aquí.","Le livre dont je t'ai parlé est là.","hablar de"],["No entiendo lo que dices.","Je ne comprends pas ce que tu dis.",""],["Es el restaurante en el que cenamos el sábado.","C'est le restaurant où on a dîné samedi.",""],["La persona que me ayudó se llama Elena.","La personne qui m'a aidé s'appelle Elena.","que sujet"]],"traps":[["El libro dont te hablé.","El libro del que te hablé.","« Dont » n'existe pas : on part de hablar de."],["Que quiero es dormir.","Lo que quiero es dormir.","« Ce que » se dit lo que."],["El chico quien vino ayer.","El chico que vino ayer.","Sans préposition, on met que, pas quien."]],"tip":"Que pour tout, el que après une préposition, lo que pour « ce que »."},
"es_si_pluscuam":{"intro":"Exprimer un regret ou refaire le passé : « si j'avais su, je serais venu ». Ce qui est arrivé ne peut plus changer, alors l'espagnol sort ses temps composés.","parts":[{"h":"La structure","p":"Dans la condition : si + hubiera + participe. Dans le résultat : habría + participe. Les deux parties parlent du passé.\n\nComme toujours, le participe ne bouge pas, et haber sert pour tous les verbes, même ir ou venir.","rows":[["condition","si lo hubiera sabido","si je l'avais su"],["résultat","habría venido","je serais venu"],["condition en -se","si lo hubiese sabido","même sens, plus écrit"],["résultat avec hubiera","hubiera venido","très courant à l'oral"]]},{"h":"Conjuguer hubiera et habría","p":"Retiens les deux colonnes : la première pour la condition, la seconde pour le résultat.","rows":[["yo","hubiera visto","habría visto"],["tú","hubieras visto","habrías visto"],["él / ella / usted","hubiera visto","habría visto"],["nosotros","hubiéramos visto","habríamos visto"],["vosotros","hubierais visto","habríais visto"],["ellos / ustedes","hubieran visto","habrían visto"]]},{"h":"Le piège du conditionnel","p":"Après si, jamais de conditionnel : « si habría sabido » est faux. Le français a la même règle : on ne dit pas « si j'aurais su ».\n\nTu peux en revanche mettre hubiera dans les deux parties : si lo hubiera sabido, hubiera venido. C'est correct et très fréquent."}],"ex":[["Si lo hubiera sabido, habría venido.","Si j'avais su, je serais venu.",""],["Si me hubieras llamado, te habría ayudado.","Si tu m'avais appelé, je t'aurais aidé.",""],["Si no hubiera llovido, habríamos ido a la playa.","S'il n'avait pas plu, nous serions allés à la plage.",""],["Si hubiéramos salido antes, no habríamos perdido el avión.","Si nous étions partis plus tôt, nous n'aurions pas raté l'avion.",""],["¿Qué habrías hecho si te hubieran despedido?","Qu'est-ce que tu aurais fait si on t'avait licencié ?","hecho : participe irrégulier"],["Si hubiese estudiado más, habría aprobado.","Si j'avais plus travaillé, j'aurais eu mon examen.","forme en -se"],["Si me lo hubieras dicho, te hubiera esperado.","Si tu me l'avais dit, je t'aurais attendu.","hubiera dans les deux parties"]],"traps":[["Si lo habría sabido, habría venido.","Si lo hubiera sabido, habría venido.","Jamais de conditionnel après si."],["Si lo hubiera sabido, sería venido.","Si lo hubiera sabido, habría venido.","Le résultat passé se forme avec haber, même pour venir."],["Si lo había sabido, habría venido.","Si lo hubiera sabido, habría venido.","Pour un regret, la condition prend le subjonctif, pas l'indicatif."]],"tip":"Pour refaire le passé : si hubiera…, habría…, et jamais habría juste après si."},
"es_cond_mixtas":{"intro":"Quand une décision d'hier change ta vie d'aujourd'hui : « si j'avais accepté ce poste, je vivrais à Madrid ». On mélange deux moments dans une seule phrase.","parts":[{"h":"Passé imaginaire, résultat présent","p":"La condition parle du passé : si + hubiera + participe. Le résultat parle de maintenant : conditionnel simple.\n\nDes mots comme ahora ou hoy aident à sentir le présent.","rows":[["si + hubiera + participe","si hubiera aceptado","si j'avais accepté"],["conditionnel simple","ahora viviría en Madrid","je vivrais à Madrid"]]},{"h":"Situation présente, résultat passé","p":"L'inverse existe aussi. La condition décrit un trait qui reste vrai aujourd'hui : si + subjonctif imparfait. Le résultat est un fait passé : habría + participe.\n\nSi fuera más organizado veut dire : il n'est pas organisé, en général, et ça a eu une conséquence.","rows":[["si + subjonctif imparfait","si fuera más organizado","s'il était plus organisé"],["habría + participe","no habría perdido el tren","il n'aurait pas raté le train"]]},{"h":"Choisir le bon temps","p":"Pose-toi deux questions. La condition parle-t-elle d'un moment précis du passé, ou d'une situation qui dure ? Le résultat se voit-il maintenant, ou est-il déjà terminé ?\n\nChaque partie prend son temps à elle. Et toujours : pas de conditionnel après si."}],"ex":[["Si hubiera aceptado ese puesto, ahora viviría en Madrid.","Si j'avais accepté ce poste, je vivrais à Madrid maintenant.",""],["Si fuera más organizado, no habría perdido el tren.","S'il était plus organisé, il n'aurait pas raté le train.",""],["Si hubieras dormido, no estarías cansado.","Si tu avais dormi, tu ne serais pas fatigué.",""],["Si hubiera estudiado medicina, ahora sería médico.","Si j'avais fait médecine, je serais médecin aujourd'hui.",""],["Si no fuera tan tímida, le habría hablado en la fiesta.","Si elle n'était pas si timide, elle lui aurait parlé à la fête.",""],["Si hubiéramos comprado la casa, hoy tendríamos jardín.","Si nous avions acheté la maison, nous aurions un jardin aujourd'hui.",""],["Si supiera inglés, habría conseguido el trabajo.","S'il parlait anglais, il aurait obtenu le poste.","savoir l'anglais : situation qui dure"]],"traps":[["Si hubiera aceptado, ahora habría vivido en Madrid.","Si hubiera aceptado, ahora viviría en Madrid.","Le résultat est au présent : conditionnel simple."],["Si sería más organizado, no habría perdido el tren.","Si fuera más organizado, no habría perdido el tren.","Après si, subjonctif imparfait, jamais de conditionnel."]],"tip":"Chaque partie garde son époque : hier avec hubiera ou habría, aujourd'hui avec fuera ou viviría."},
"es_aunque":{"intro":"Pour dire « bien que » ou « même si », l'espagnol n'a qu'un mot : aunque. C'est le mode du verbe qui fait la différence de sens.","parts":[{"h":"Aunque + indicatif : un fait","p":"Avec l'indicatif, tu présentes la chose comme vraie et tu l'assumes : aunque está cansado, sigue. Il est fatigué, c'est sûr.\n\nAttention : « bien que » prend le subjonctif en français, mais pour un fait, l'espagnol garde l'indicatif.","rows":[["aunque + présent","Aunque está cansado, sigue.","il est vraiment fatigué"],["aunque + passé","Aunque llovía, salimos.","il pleuvait vraiment"]]},{"h":"Aunque + subjonctif : une hypothèse ou un fait écarté","p":"Avec le subjonctif, tu parles d'une chose possible, future, ou que tu ne veux pas discuter : aunque llueva mañana, saldremos.\n\nOn l'emploie aussi pour un fait qui ne compte pas : aunque no me creas, es verdad. Que tu me croies ou non, peu importe.","rows":[["aunque + subjonctif présent","Aunque llueva, saldremos.","s'il pleut, peu importe"],["aunque + subjonctif présent","Aunque no me creas, es verdad.","ton avis ne change rien"],["aunque + subjonctif imparfait","Aunque tuviera dinero, no lo compraría.","même si j'avais, irréel"]]},{"h":"Comparer avec le français","p":"Le français choisit le mot : « bien que » ou « même si ». L'espagnol garde aunque et choisit le mode.\n\nUne astuce : si tu peux ajouter « et c'est le cas », mets l'indicatif. Si tu peux ajouter « peut-être » ou « peu importe », mets le subjonctif.","rows":[["Aunque es caro, lo compro.","Bien que ce soit cher, je l'achète.","je connais le prix"],["Aunque sea caro, lo compraré.","Même si c'est cher, je l'achèterai.","je ne connais pas le prix"]]}],"ex":[["Aunque llueve, salgo a correr.","Bien qu'il pleuve, je sors courir.","il pleut vraiment"],["Aunque llueva mañana, saldremos.","Même s'il pleut demain, nous sortirons.","hypothèse"],["Aunque está cansado, sigue trabajando.","Bien qu'il soit fatigué, il continue à travailler.",""],["Aunque no me creas, es verdad.","Même si tu ne me crois pas, c'est vrai.",""],["Aunque vivo muy cerca, siempre llego tarde.","Bien que j'habite tout près, j'arrive toujours en retard.",""],["Aunque me lo pidas de rodillas, no voy a ir.","Même si tu me le demandes à genoux, je n'irai pas.",""],["Aunque tuviera tiempo, no vería esa serie.","Même si j'avais le temps, je ne regarderais pas cette série.","irréel : subjonctif imparfait"]],"traps":[["Aunque llueve mañana, saldremos.","Aunque llueva mañana, saldremos.","Pour une simple hypothèse sur demain, aunque prend le subjonctif."],["Mismo si llueve, saldremos.","Aunque llueva, saldremos.","« Même si » ne se traduit pas mot à mot : on dit aunque."],["Aunque tendría dinero, no lo compraría.","Aunque tuviera dinero, no lo compraría.","Pour l'irréel, subjonctif imparfait, jamais de conditionnel après aunque."]],"tip":"Aunque + indicatif : c'est sûr. Aunque + subjonctif : peut-être, ou peu importe."},
"es_perifrasis":{"intro":"Pour dire depuis combien de temps tu fais quelque chose, que tu viens de le faire, que tu recommences ou que tu arrêtes. L'espagnol a quatre tournures très courantes pour ça.","parts":[{"h":"llevar + durée + gérondif","p":"Pour « faire quelque chose depuis », l'espagnol aime llevar conjugué, puis la durée, puis le gérondif : llevo dos años aprendiendo español.\n\nLe gérondif se forme avec -ando (-ar) ou -iendo (-er, -ir). Desde hace existe aussi : aprendo español desde hace dos años.","rows":[["llevo + durée + gérondif","Llevo dos años aprendiendo español.","j'apprends depuis deux ans"],["llevamos + durée + gérondif","Llevamos una hora esperando.","on attend depuis une heure"],["llevar + durée + sin + infinitif","Llevo un mes sin fumar.","je ne fume plus depuis un mois"]]},{"h":"acabar de, volver a, dejar de","p":"Ces verbes se construisent avec une préposition et un infinitif. Le premier verbe se conjugue, l'infinitif ne bouge pas.","rows":[["acabar de + infinitif","Acabo de llegar.","venir de"],["volver a + infinitif","Ha vuelto a fumar.","refaire, recommencer"],["dejar de + infinitif","He dejado de tomar café.","arrêter de"],["empezar a + infinitif","Empecé a correr en mayo.","commencer à"]]},{"h":"Le piège de volver a","p":"Volver seul veut dire revenir : vuelvo a casa, je rentre à la maison. Mais volver a + infinitif veut dire refaire : vuelvo a llamar, je rappelle.\n\nRegarde ce qui suit le a. Un lieu : revenir. Un infinitif : recommencer."}],"ex":[["Llevo dos años aprendiendo español.","J'apprends l'espagnol depuis deux ans.",""],["Acabo de llegar a la estación.","Je viens d'arriver à la gare.",""],["Ha vuelto a fumar.","Il a recommencé à fumer.",""],["He dejado de tomar café.","J'ai arrêté de boire du café.",""],["¿Cuánto tiempo llevas viviendo aquí?","Depuis combien de temps tu habites ici ?",""],["Te vuelvo a llamar en cinco minutos.","Je te rappelle dans cinq minutes.","volver a : refaire"],["Acabamos de comer, no tenemos hambre.","On vient de manger, on n'a pas faim.",""],["Deja de mirar el móvil, por favor.","Arrête de regarder ton portable, s'il te plaît.","dejar de à l'impératif"]],"traps":[["Vengo de llegar.","Acabo de llegar.","« Venir de » se dit acabar de, pas venir de."],["Estoy aprendiendo español desde dos años.","Llevo dos años aprendiendo español.","Pour « depuis » + durée : llevar + durée + gérondif, ou desde hace."],["Ha recomenzado a fumar.","Ha vuelto a fumar.","Pour « recommencer à », l'espagnol dit volver a."]],"tip":"Llevo… : depuis. Acabo de : je viens de. Vuelvo a : je refais. Dejo de : j'arrête."},
"es_conectores":{"intro":"Pour nuancer un avis ou écrire un e-mail bien construit : « c'est cher ; cependant, ça vaut le coup », « malgré la pluie, nous sommes sortis ». Ces connecteurs rendent ton espagnol plus fluide.","parts":[{"h":"sin embargo, no obstante","p":"Les deux veulent dire « cependant ». Ils relient deux phrases complètes. On les met souvent après un point-virgule ou un point, et on les fait suivre d'une virgule.\n\nSin embargo sert partout. No obstante est plus soutenu, pour l'écrit ou un discours.","rows":[["sin embargo","Es caro; sin embargo, merece la pena.","courant"],["no obstante","El plan es bueno. No obstante, hay riesgos.","soutenu"]]},{"h":"a pesar de, a pesar de que","p":"A pesar de veut dire « malgré ». Il est suivi d'un nom ou d'un infinitif : a pesar de la lluvia, a pesar de estar cansada.\n\nPour une phrase avec un verbe conjugué, ajoute que : a pesar de que es tarde. Pese a s'utilise comme a pesar de, en plus soutenu.","rows":[["a pesar de + nom","A pesar de la lluvia, salimos.","malgré"],["a pesar de + infinitif","A pesar de estar cansada, vino.","même sujet"],["a pesar de que + verbe","A pesar de que es tarde, sigo trabajando.","bien que"],["pese a + nom","Pese a la crisis, abrieron la tienda.","soutenu"]]},{"h":"Le mode après a pesar de que","p":"Comme aunque, a pesar de que prend l'indicatif pour un fait réel : a pesar de que es tarde. Le subjonctif sert pour une hypothèse ou un fait qu'on écarte.\n\nLe français « bien que » prend le subjonctif. L'espagnol, pour un fait, garde l'indicatif."}],"ex":[["A pesar de la lluvia, salimos.","Malgré la pluie, nous sommes sortis.",""],["Es caro; sin embargo, merece la pena.","C'est cher ; cependant, ça vaut le coup.",""],["A pesar de que es tarde, sigo trabajando.","Bien qu'il soit tard, je travaille encore.","indicatif : c'est un fait"],["A pesar de estar enfermo, fue a la reunión.","Même malade, il est allé à la réunion.","infinitif, même sujet"],["Pese a sus esfuerzos, no consiguió el puesto.","Malgré ses efforts, il n'a pas obtenu le poste.","soutenu"],["El hotel era viejo; no obstante, estaba muy limpio.","L'hôtel était vieux ; néanmoins, il était très propre.",""],["Me gusta mi trabajo. Sin embargo, quiero cambiar de ciudad.","J'aime mon travail. Pourtant, je veux changer de ville.",""]],"traps":[["A pesar de que la lluvia, salimos.","A pesar de la lluvia, salimos.","Devant un nom, pas de que."],["A pesar de es tarde, sigo trabajando.","A pesar de que es tarde, sigo trabajando.","Devant un verbe conjugué, il faut que."]],"tip":"Un nom après a pesar de, un verbe conjugué après a pesar de que."},
"es_como_si":{"intro":"Pour décrire une attitude qui ne colle pas à la réalité : « il parle comme s'il savait tout ». Là où le français met l'imparfait, l'espagnol met le subjonctif.","parts":[{"h":"como si + subjonctif imparfait","p":"Après como si, le verbe est au subjonctif imparfait quand on parle du même moment : habla como si lo supiera todo.\n\nLe verbe principal, lui, reste à son temps normal : présent, passé ou futur.","rows":[["saber","como si lo supiera todo","comme s'il savait tout"],["ser","como si fuera su casa","comme si c'était chez lui"],["tener","como si tuviera prisa","comme s'il était pressé"],["pasar","como si no pasara nada","comme si de rien n'était"]]},{"h":"como si + plus-que-parfait du subjonctif","p":"Pour une chose antérieure, on met hubiera + participe : me miras como si nunca me hubieras visto.\n\nC'est l'équivalent de « comme si tu ne m'avais jamais vu ».","rows":[["hubiera + participe","como si nunca me hubieras visto","comme si tu ne m'avais jamais vu"],["hubiera + participe","como si no hubiera dormido","comme s'il n'avait pas dormi"]]},{"h":"La différence avec le français","p":"Le français dit « comme s'il savait », à l'imparfait de l'indicatif. En espagnol, como si sabía est faux.\n\nUne expression à retenir : hacer como si nada, faire comme si de rien n'était."}],"ex":[["Habla como si lo supiera todo.","Il parle comme s'il savait tout.",""],["Hace como si nada.","Elle fait comme si de rien n'était.","expression figée"],["Me miras como si nunca me hubieras visto.","Tu me regardes comme si tu ne m'avais jamais vu.",""],["Se comporta como si fuera el jefe.","Il se comporte comme s'il était le chef.",""],["Comimos como si no hubiéramos comido en una semana.","On a mangé comme si on n'avait rien mangé depuis une semaine.",""],["Salió corriendo como si tuviera prisa.","Il est parti en courant, comme s'il était pressé.",""],["Gasta dinero como si fuera rico.","Il dépense de l'argent comme s'il était riche.",""]],"traps":[["Habla como si sabe todo.","Habla como si lo supiera todo.","Après como si, jamais d'indicatif."],["Habla como si sabía todo.","Habla como si lo supiera todo.","L'imparfait français se traduit ici par le subjonctif imparfait."],["Me miras como si nunca me habías visto.","Me miras como si nunca me hubieras visto.","Pour une chose antérieure, hubiera + participe."]],"tip":"Como si ne supporte que le subjonctif : supiera, fuera, hubiera visto."},
"es_modismos":{"intro":"Les expressions imagées donnent du relief à ce que tu dis : « ça coûte les yeux de la tête », « il pleut des cordes ». Chaque langue a ses images, il faut apprendre les siennes en bloc.","parts":[{"h":"Ne pas traduire mot à mot","p":"Une expression idiomatique a un sens global. Si tu la traduis mot par mot, un Espagnol ne comprendra pas, ou il sourira.\n\nCherche l'équivalent entier. Parfois l'image ressemble au français, parfois elle n'a rien à voir."},{"h":"Des images proches du français","p":"Ici, l'image est presque la même. Le danger, c'est le petit détail qui change.","rows":[["coûter les yeux de la tête","Cuesta un ojo de la cara.","un seul œil, celui du visage"],["être dans la lune","Está en las nubes.","dans les nuages"],["comme un poisson dans l'eau","Está como pez en el agua.","sans article"],["vendre la peau de l'ours","No hay que vender la piel del oso antes de cazarlo.","cazar : chasser"]]},{"h":"Des images différentes","p":"Là, il faut tout apprendre : l'image espagnole n'a rien à voir avec la française.","rows":[["il pleut des cordes","Llueve a cántaros.","à pleines cruches"],["être dans la lune","Estar en Babia.","Babia : une région de León"],["ne pas mâcher ses mots","No tener pelos en la lengua.","pas de poils sur la langue"],["tomber à pic","Venir como anillo al dedo.","comme une bague au doigt"],["poser un lapin","Dar plantón.","dar plantón a alguien"]]}],"ex":[["Este piso cuesta un ojo de la cara.","Cet appartement coûte les yeux de la tête.",""],["Coge el paraguas, que llueve a cántaros.","Prends le parapluie, il pleut des cordes.","coger : prendre, en Espagne"],["Perdona, estaba en las nubes.","Pardon, j'étais dans la lune.",""],["Mi abuela no tiene pelos en la lengua.","Ma grand-mère ne mâche pas ses mots.",""],["Tu ayuda me viene como anillo al dedo.","Ton aide tombe à pic.",""],["Ayer mi amigo me dio plantón.","Hier, mon ami m'a posé un lapin.",""],["En su nuevo trabajo está como pez en el agua.","Dans son nouveau travail, il est comme un poisson dans l'eau.",""],["No hay que vender la piel del oso antes de cazarlo.","Il ne faut pas vendre la peau de l'ours avant de l'avoir tué.",""]],"traps":[["Cuesta los ojos de la cabeza.","Cuesta un ojo de la cara.","L'image espagnole, c'est un seul œil, celui du visage."],["Llueve cuerdas.","Llueve a cántaros.","Les cordes françaises deviennent des cruches en espagnol."],["Me puso un conejo.","Me dio plantón.","« Poser un lapin » n'a pas d'équivalent animal en espagnol."]],"tip":"Une expression s'apprend en bloc, avec son image espagnole, jamais mot à mot."},
"es_probabilidad":{"intro":"Quand tu fais une supposition : « où peut-il bien être ? », « il devait être dix heures ». L'espagnol n'a pas besoin de « devoir » ou de « peut-être » : il change juste le temps du verbe.","parts":[{"h":"Le futur pour supposer au présent","p":"Le futur simple sert à deviner quelque chose de maintenant : dónde estará veut dire « où peut-il bien être ? ».\n\nTendrá cuarenta años ne parle pas de l'avenir : il doit avoir quarante ans, aujourd'hui.","rows":[["certitude","Está en casa.","il est à la maison"],["supposition","Estará en casa.","il doit être à la maison"],["question","¿Qué hora será?","quelle heure peut-il bien être ?"]]},{"h":"Le conditionnel pour supposer au passé","p":"Pour deviner quelque chose du passé, on recule d'un cran : le conditionnel remplace l'imparfait ou le passé simple.\n\nSerían las diez veut dire « il devait être dix heures ».","rows":[["certitude","Eran las diez.","il était dix heures"],["supposition","Serían las diez.","il devait être dix heures"],["certitude","Tenía veinte años.","il avait vingt ans"],["supposition","Tendría veinte años.","il devait avoir vingt ans"]]},{"h":"Le futur antérieur pour un passé récent","p":"Pour une supposition sur une chose qui vient de se passer, on prend habrá + participe : lo habrá olvidado, elle aura oublié.\n\nLe français a la même tournure (« il se sera trompé »), mais l'espagnol l'emploie beaucoup plus souvent.","rows":[["certitude","Ha salido.","il est sorti"],["supposition","Habrá salido.","il a dû sortir"]]}],"ex":[["¿Dónde estará Marta?","Où peut bien être Marta ?",""],["Tendrá unos cuarenta años.","Il doit avoir dans les quarante ans.",""],["Serían las diez cuando llegó.","Il devait être dix heures quand il est arrivé.",""],["Se le habrá olvidado.","Elle aura oublié.","olvidársele : sortir de la tête"],["No contesta. Estará durmiendo.","Il ne répond pas. Il doit dormir.",""],["¿Quién llamaría tan tarde anoche?","Qui a bien pu appeler si tard hier soir ?","conditionnel : passé"],["Habrá mucho tráfico, por eso tarda.","Il doit y avoir beaucoup de circulation, c'est pour ça qu'il tarde.",""],["Estaría cansado, por eso no vino.","Il devait être fatigué, c'est pour ça qu'il n'est pas venu.",""]],"traps":[["¿Dónde puede bien estar?","¿Dónde estará?","« Peut bien » ne se traduit pas : le futur suffit."],["Serán las diez cuando llegó.","Serían las diez cuando llegó.","Pour une supposition sur le passé, c'est le conditionnel."]],"tip":"Pour deviner, avance le temps d'un cran : maintenant devient futur, hier devient conditionnel."},
"es_relativo_subj":{"intro":"Quand tu décris une chose que tu cherches sans savoir si elle existe : « je cherche un appartement qui ait une terrasse ». Le mode du verbe dit si la chose est réelle ou imaginée.","parts":[{"h":"Connu ou inconnu ?","p":"Si tu parles d'une chose précise, qui existe : indicatif. Vivo en un piso que tiene terraza.\n\nSi la chose est seulement souhaitée, ou si tu ne sais pas si elle existe : subjonctif. Busco un piso que tenga terraza.","rows":[["connu : indicatif","Vivo en un piso que tiene terraza.","il existe"],["inconnu : subjonctif","Busco un piso que tenga terraza.","peut-être"],["connu : indicatif","Tengo un amigo que habla ruso.","je le connais"],["inconnu : subjonctif","¿Conoces a alguien que hable ruso?","existe-t-il ?"]]},{"h":"Quand ça n'existe pas","p":"Après no hay nadie que, no hay nada que ou ningún… que, la chose n'existe pas. Le subjonctif est obligatoire.\n\nLe français fait parfois pareil : « il n'y a personne qui puisse m'aider ».","rows":[["no hay nadie que","No hay nadie que pueda ayudarme.","il n'y a personne qui"],["no hay nada que","No hay nada que me guste.","il n'y a rien qui"],["ningún… que","No conozco ningún bar que abra tan tarde.","aucun… qui"]]},{"h":"Lo que, el que, quien + subjonctif","p":"Même logique avec lo que, el que ou quien. Haz lo que quieras : ce que tu voudras, je ne sais pas encore quoi.\n\nPour l'avenir, le français met le futur, l'espagnol le subjonctif : el que llegue primero ganará.","rows":[["lo que + subjonctif","Haz lo que quieras.","ce que tu voudras"],["el que + subjonctif","El que llegue primero ganará.","celui qui arrivera"],["quien + subjonctif","Quien quiera venir, que venga.","qui voudra"]]}],"ex":[["Busco un piso que tenga terraza.","Je cherche un appartement qui ait une terrasse.",""],["¿No hay nadie que pueda ayudarme?","Il n'y a personne qui puisse m'aider ?",""],["Haz lo que quieras.","Fais ce que tu veux.",""],["El que llegue primero ganará.","Celui qui arrivera le premier gagnera.","futur en français, subjonctif en espagnol"],["Vivo en un piso que tiene terraza.","J'habite dans un appartement qui a une terrasse.","connu : indicatif"],["Necesitamos a alguien que sepa programar.","Nous avons besoin de quelqu'un qui sache programmer.",""],["Pide lo que te apetezca, invito yo.","Commande ce qui te fait envie, c'est moi qui invite.",""],["No conozco a nadie que viva en Sevilla.","Je ne connais personne qui habite à Séville.",""]],"traps":[["Busco un piso que tiene terraza.","Busco un piso que tenga terraza.","Si tu ne sais pas encore quel appartement, le subjonctif s'impose."],["El que llegará primero ganará.","El que llegue primero ganará.","Pour l'avenir dans une relative, subjonctif et non futur."],["No hay nadie que puede ayudarme.","No hay nadie que pueda ayudarme.","Une chose qui n'existe pas appelle le subjonctif."]],"tip":"Je le connais : indicatif. Je l'imagine ou je le cherche : subjonctif."},
"es_de_inf":{"intro":"Dans un discours soigné ou un texte, on peut remplacer « si » par une tournure plus élégante : de haberlo sabido, « si je l'avais su ». Court et très espagnol.","parts":[{"h":"La forme","p":"De + infinitif simple pour une condition sur le présent ou l'avenir : de seguir así, si on continue ainsi.\n\nDe + haber + participe pour une condition sur le passé : de haberlo sabido, si je l'avais su. Les pronoms se collent à haber.","rows":[["de + infinitif","de seguir así","si on continue ainsi"],["de + infinitif","de necesitar algo","si tu as besoin de quelque chose"],["de + haber + participe","de haberlo sabido","si je l'avais su"],["de + haber + participe","de haber salido antes","si on était partis plus tôt"]]},{"h":"Le reste de la phrase","p":"La deuxième partie garde le temps qu'elle aurait avec si : futur, impératif, conditionnel ou habría + participe.\n\nDe haberlo sabido, no habría venido équivaut à si lo hubiera sabido, no habría venido.","rows":[["De seguir así, llegaremos tarde.","Si seguimos así, llegaremos tarde.","futur"],["De necesitar algo, llámame.","Si necesitas algo, llámame.","impératif"],["De haberlo sabido, no habría venido.","Si lo hubiera sabido, no habría venido.","passé"]]},{"h":"Un seul sujet, un registre soigné","p":"En général, les deux parties ont le même sujet. Sinon, la phrase devient vite floue.\n\nC'est une tournure de registre soigné. À l'oral détendu, si reste plus fréquent."}],"ex":[["De haberlo sabido, no habría venido.","Si j'avais su, je ne serais pas venu.",""],["De seguir así, vamos a llegar tarde.","Si on continue comme ça, on va arriver en retard.",""],["De necesitar algo, llámame.","Si tu as besoin de quelque chose, appelle-moi.",""],["De tener más tiempo, aprendería a tocar la guitarra.","Si j'avais plus de temps, j'apprendrais à jouer de la guitare.","hypothèse sur le présent"],["De haber salido antes, habríamos cogido el tren.","Si nous étions partis plus tôt, nous aurions eu le train.",""],["De no ser por ti, me habría perdido.","Sans toi, je me serais perdu.","de no ser por : sans"],["De ganar el partido, el equipo jugará la final.","Si l'équipe gagne le match, elle jouera la finale.",""]],"traps":[["De lo haber sabido, no habría venido.","De haberlo sabido, no habría venido.","Avec un infinitif, le pronom se colle à la fin."],["De hubiera sabido, no habría venido.","De haber sabido, no habría venido.","Après de, toujours un infinitif, jamais un verbe conjugué."]],"tip":"De + infinitif, c'est un si en version courte : de haberlo sabido, si je l'avais su."},
"es_registro":{"intro":"Écrire à un hôtel, à une administration ou à un futur employeur demande le bon ton. L'espagnol a ses formules de politesse, avec usted et quelques temps qui adoucissent.","parts":[{"h":"Usted : la 3e personne","p":"Usted correspond au « vous » de politesse. Il se conjugue comme él ou ella : usted habla inglés. Au pluriel, ustedes se conjugue comme ellos.\n\nLes pronoms suivent : le, lo, la, su. Su reserva veut dire « votre réservation ».","rows":[["tú","¿Puedes ayudarme?","informel"],["usted","¿Puede ayudarme?","formel"],["ton, ta","tu reserva","informel"],["votre","su reserva","formel"]]},{"h":"Adoucir une demande","p":"Quiero est direct, parfois un peu sec. Quisiera ou me gustaría sont plus doux. Le conditionnel podría rend une question plus polie.\n\nLe agradecería que + subjonctif imparfait est la formule écrite par excellence : « je vous serais reconnaissant de… ».","rows":[["quiero","Quiero una habitación.","direct"],["quisiera","Quisiera reservar una habitación.","poli"],["me gustaría","Me gustaría hablar con el director.","poli"],["¿podría…?","¿Podría decirme la hora?","pourriez-vous"],["le agradecería que","Le agradecería que me respondiera pronto.","écrit, formel"]]},{"h":"Tú ou usted ?","p":"En Espagne, le tú est très courant, même avec des inconnus de ton âge ou au travail. Usted reste de mise avec une personne âgée, dans un courrier officiel ou avec un service client.\n\nEn Amérique latine, usted est souvent plus fréquent. Dans le doute, commence par usted : l'autre te proposera le tú."}],"ex":[["Quisiera reservar una habitación para dos noches.","Je voudrais réserver une chambre pour deux nuits.",""],["Le agradecería que me respondiera pronto.","Je vous serais reconnaissant de me répondre rapidement.",""],["¿Podría decirme la hora, por favor?","Pourriez-vous me dire l'heure, s'il vous plaît ?",""],["¿Me podría traer la cuenta?","Pourriez-vous m'apporter l'addition ?",""],["Me gustaría hablar con el responsable.","J'aimerais parler au responsable.",""],["Estimada señora García:","Chère Madame García,","début de lettre : deux-points en espagnol"],["Le adjunto mi currículum.","Je vous joins mon CV.",""],["¿Sería posible cambiar la fecha de la cita?","Serait-il possible de changer la date du rendez-vous ?",""]],"traps":[["¿Usted puedes ayudarme?","¿Usted puede ayudarme?","Usted se conjugue à la 3e personne."],["Le agradecería que me responde pronto.","Le agradecería que me respondiera pronto.","Après le agradecería que, subjonctif imparfait."],["Querido señor director:","Estimado señor director:","Dans un courrier formel, on écrit estimado ; querido est pour les proches."]],"tip":"Pour être poli, recule le verbe : quiero devient quisiera, puede devient podría."},
"es_por_mucho_que":{"intro":"Pour dire qu'un effort ne changera rien : « tu as beau insister, je n'irai pas ». Le français dit « avoir beau », l'espagnol dit por mucho que ou por más que.","parts":[{"h":"La forme","p":"Por mucho que et por más que veulent dire la même chose. Ils sont suivis d'un verbe conjugué, puis la phrase principale dit que le résultat ne change pas.\n\nAvec un nom, on dit por mucho + nom + que, et mucho s'accorde : por mucho dinero que tenga, por muchas veces que lo repitas.","rows":[["por mucho que + verbe","Por mucho que insistas, no iré.",""],["por más que + verbe","Por más que insistas, no iré.","même sens"],["por mucho + nom + que","Por mucho dinero que tenga, no será feliz.","mucho s'accorde"]]},{"h":"Subjonctif ou indicatif ?","p":"Comme avec aunque, le mode change le sens. Le subjonctif présente une hypothèse ou un futur : por mucho que insistas, no iré.\n\nL'indicatif présente un fait réel, souvent répété : por más que busco, no encuentro mis llaves. Je cherche vraiment, et ça ne marche pas.","rows":[["subjonctif : hypothèse","Por mucho que corramos, no llegaremos.","on aura beau courir"],["indicatif : fait","Por más que busco, no las encuentro.","j'ai beau chercher"],["indicatif passé : fait","Por más que lo intenté, no pude.","j'ai eu beau essayer"]]},{"h":"Comparer avec le français","p":"En français, on conjugue « avoir beau », puis vient un infinitif. En espagnol, pas de verbe « avoir » : c'est l'action elle-même qui se conjugue après que.\n\n« Tu as beau insister » devient por mucho que insistas : c'est insistir qui se conjugue."}],"ex":[["Por mucho que insistas, no iré.","Tu as beau insister, je n'irai pas.",""],["Por más que corramos, no llegaremos a tiempo.","On aura beau courir, on n'arrivera pas à temps.",""],["Por más que busco, no encuentro mis llaves.","J'ai beau chercher, je ne trouve pas mes clés.","indicatif : fait réel"],["Por mucho que estudia, siempre se pone nervioso en los exámenes.","Il a beau réviser, il est toujours stressé aux examens.","fait répété : indicatif"],["Por mucho dinero que tenga, no será feliz.","Il aura beau avoir de l'argent, il ne sera pas heureux.","mucho + nom"],["Por más que se lo expliqué, no lo entendió.","J'ai eu beau le lui expliquer, il n'a pas compris.",""],["Por mucho que me lo pidas, no te voy a dejar el coche.","Tu as beau me le demander, je ne te prêterai pas la voiture.",""]],"traps":[["Tienes bello insistir, no iré.","Por mucho que insistas, no iré.","« Avoir beau » ne se traduit pas mot à mot."],["Por mucho que insistirás, no iré.","Por mucho que insistas, no iré.","Pas de futur après por mucho que : le subjonctif le remplace."]],"tip":"Avoir beau, c'est por mucho que : subjonctif si c'est à venir, indicatif si c'est déjà vrai."}
});
})();
